const L1: &str = "Western (ISO 8859-1)";
const SJIS: &str = "Japanese (Shift JIS)";
const GBK: &str = "Chinese Simplified (GBK)";
const EUCKR: &str = "Korean (EUC-KR)";
const U8: &str = "UTF-8";
const U16LE: &str = "UTF-16 LE";

