// ---------------------------------------------------------------- report
struct Rep {
    name: String,
    lines: Vec<String>,
    cells: usize,
    fails: usize,
}
impl Rep {
    fn new(name: &str) -> Self {
        Self {
            name: name.into(),
            lines: vec![],
            cells: 0,
            fails: 0,
        }
    }
    fn cell(&mut self, id: &str, problems: Vec<String>) {
        self.cells += 1;
        if !problems.is_empty() {
            self.fails += 1;
            for p in problems {
                self.lines.push(format!("FAIL\t{id}\t{p}"));
            }
        }
    }
    fn note(&mut self, id: &str, msg: String) {
        self.lines.push(format!("NOTE\t{id}\t{msg}"));
    }
}
impl Drop for Rep {
    fn drop(&mut self) {
        let dir = std::env::var_os("R20_MATRIX_REPORT").map_or_else(
            || std::env::temp_dir().join(format!("velocity-r20-matrix-{}", std::process::id())),
            PathBuf::from,
        );
        let _ = std::fs::create_dir_all(&dir);
        let mut out = format!("CELLS\t{}\tFAILS\t{}\n", self.cells, self.fails);
        for l in &self.lines {
            out.push_str(l);
            out.push('\n');
        }
        std::fs::write(dir.join(format!("{}.tsv", self.name)), out).unwrap();
        eprintln!(
            "{}: {} cells, {} failures",
            self.name, self.cells, self.fails
        );
        if !std::thread::panicking() {
            assert_eq!(self.fails, 0, "{}: see {}", self.name, dir.display());
        }
    }
}

// ---------------------------------------------------------------- codecs
fn canon(name: &str) -> String {
    vel_fileio::encoding(name).unwrap().name().to_string()
}
fn norm(s: &str) -> String {
    s.replace("\r\n", "\n").replace('\r', "\n")
}
fn enc(text: &str, name: &str, bom: bool) -> Option<Vec<u8>> {
    let c = vel_fileio::encoding(name).unwrap();
    let mut out = Vec::new();
    match c.name() {
        "UTF-8" => {
            if bom {
                out.extend([0xef, 0xbb, 0xbf]);
            }
            out.extend(text.as_bytes());
        }
        "UTF-16LE" => {
            if bom {
                out.extend([0xff, 0xfe]);
            }
            for u in text.encode_utf16() {
                out.extend(u.to_le_bytes());
            }
        }
        "UTF-16BE" => {
            if bom {
                out.extend([0xfe, 0xff]);
            }
            for u in text.encode_utf16() {
                out.extend(u.to_be_bytes());
            }
        }
        _ => {
            if bom {
                return None;
            }
            let (b, _, err) = c.encode(text);
            if err {
                return None;
            }
            out.extend(b.iter());
        }
    }
    Some(out)
}
fn strict(name: &str, bytes: &[u8]) -> Option<String> {
    let c = vel_fileio::encoding(name).ok()?;
    c.decode_without_bom_handling_and_without_replacement(bytes)
        .map(|s| norm(&s))
}
fn bom_of(bytes: &[u8]) -> Option<(&'static str, usize)> {
    if bytes.starts_with(&[0xef, 0xbb, 0xbf]) {
        Some(("UTF-8", 3))
    } else if bytes.starts_with(&[0xff, 0xfe]) {
        Some(("UTF-16LE", 2))
    } else if bytes.starts_with(&[0xfe, 0xff]) {
        Some(("UTF-16BE", 2))
    } else {
        None
    }
}
fn signature(bytes: &[u8]) -> bool {
    bytes.starts_with(b"\x89PNG\r\n\x1a\n")
}
// Own simple heuristic: ASCII text interleaved with NULs in one byte order.
fn my_utf16(bytes: &[u8]) -> Option<&'static str> {
    if bytes.len() < 4 || !bytes.len().is_multiple_of(2) {
        return None;
    }
    let printable = |b: u8| b.is_ascii_graphic() || matches!(b, b' ' | b'\n' | b'\r' | b'\t');
    let le = bytes.chunks(2).all(|p| p[1] == 0 && printable(p[0]));
    let be = bytes.chunks(2).all(|p| p[0] == 0 && printable(p[1]));
    match (le, be) {
        (true, false) => Some("UTF-16LE"),
        (false, true) => Some("UTF-16BE"),
        _ => None,
    }
}

#[derive(Clone, Debug, PartialEq)]
enum Exp {
    Text {
        text: String,
        codec: String,
        chosen: bool,
    },
    Binary,
    /// Fallback failed strictly: replacement characters plus a file-named notice.
    Replaced {
        text: String,
        codec: String,
    },
}
fn lossy(name: &str, bytes: &[u8]) -> String {
    let c = vel_fileio::encoding(name).unwrap();
    norm(&c.decode_without_bom_handling(bytes).0)
}
/// Claimed order, independently implemented: BOM, binary signature, explicit
/// choice (non-UTF-16 choices skipped on NUL evidence unless `rule_strict`),
/// valid UTF-8, NUL-gated UTF-16, binary, configured fallback.
fn oracle(bytes: &[u8], choice: Option<&str>, fallback: &str, rule_strict: bool) -> Exp {
    let chosen = choice.map(canon);
    let text = |name: &str, s: String| Exp::Text {
        text: s,
        codec: name.into(),
        chosen: chosen.as_deref() == Some(name),
    };
    let fb = canon(fallback);
    if let Some((name, skip)) = bom_of(bytes) {
        return match strict(name, &bytes[skip..]) {
            Some(s) => text(name, s),
            None => match strict(&fb, bytes) {
                Some(s) => Exp::Text {
                    text: s,
                    codec: fb.clone(),
                    chosen: false,
                },
                None => Exp::Replaced {
                    text: lossy(&fb, bytes),
                    codec: fb.clone(),
                },
            },
        };
    }
    if signature(bytes) {
        return Exp::Binary;
    }
    let nul = bytes.contains(&0);
    if let Some(c) = &chosen
        && (!nul || c.starts_with("UTF-16") || rule_strict)
        && let Some(s) = strict(c, bytes)
    {
        return text(c, s);
    }
    if !nul && let Ok(s) = std::str::from_utf8(bytes) {
        return text("UTF-8", norm(s));
    }
    if nul {
        return match my_utf16(bytes).and_then(|n| strict(n, bytes).map(|s| (n, s))) {
            Some((n, s)) => text(n, s),
            None => Exp::Binary,
        };
    }
    match strict(&fb, bytes) {
        Some(s) => text(&fb, s),
        None => Exp::Replaced {
            text: lossy(&fb, bytes),
            codec: fb.clone(),
        },
    }
}

// ---------------------------------------------------------------- samples
#[derive(Clone, Debug, PartialEq)]
enum Truth {
    Text(String, &'static str),
    Binary,
    Ambiguous,
}
#[derive(Clone)]
struct Sample {
    name: &'static str,
    bytes: Vec<u8>,
    truth: Truth,
}
fn s(name: &'static str, text: &str, codec: &'static str, bom: bool) -> Sample {
    Sample {
        name,
        bytes: enc(text, codec, bom).unwrap(),
        truth: Truth::Text(norm(text), codec),
    }
}
fn raw(name: &'static str, bytes: &[u8], truth: Truth) -> Sample {
    Sample {
        name,
        bytes: bytes.to_vec(),
        truth,
    }
}
