fn auto_det(s: &Sample, fb: &str) -> bool {
    match &s.truth {
        Truth::Binary => true,
        Truth::Ambiguous => false,
        Truth::Text(_, codec) => {
            bom_of(&s.bytes).is_some()
                || *codec == "UTF-8"
                || (codec.starts_with("UTF-16") && s.bytes.contains(&0))
                || (*codec == fb && std::str::from_utf8(&s.bytes).is_err())
        }
    }
}
fn determinable(s: &Sample, choice: Option<&str>, fallback: &str) -> bool {
    let fb = canon(fallback);
    let Some(c) = choice.map(canon) else {
        return auto_det(s, &fb);
    };
    if bom_of(&s.bytes).is_some() || signature(&s.bytes) {
        return true;
    }
    if let Truth::Text(_, codec) = &s.truth
        && c == *codec
    {
        return true;
    }
    let allowed = !s.bytes.contains(&0) || c.starts_with("UTF-16");
    if allowed && strict(&c, &s.bytes).is_some() {
        return false;
    }
    auto_det(s, &fb)
}

// ---------------------------------------------------------------- app harness
#[derive(Clone, Debug, PartialEq)]
struct Shown {
    binary: bool,
    text: String,
    codec: String,
    bom: bool,
    chosen: bool,
    preferred: Option<String>,
    dirty: bool,
}
fn shown(a: &App) -> Shown {
    let t = &a.workspace.tabs[a.workspace.active];
    Shown {
        binary: t.editor.binary.is_some(),
        text: a.workspace.editor().text.to_string(),
        codec: t.format.encoding.clone(),
        bom: t.format.bom,
        chosen: t.encoding_chosen,
        preferred: t.preferred_encoding.clone(),
        dirty: t.dirty(),
    }
}
fn mojibake(sh: &Shown, s: &Sample, choice: Option<&str>, fallback: &str) -> Option<String> {
    if !determinable(s, choice, fallback) {
        return None;
    }
    match &s.truth {
        Truth::Binary => {
            (!sh.binary).then(|| format!("MOJIBAKE binary shown as text {:?}", sh.text))
        }
        Truth::Text(t, codec) => (sh.binary || sh.text != *t).then(|| {
            format!(
                "MOJIBAKE truth {:?}({codec}) shown {:?}({}) bin={}",
                t, sh.text, sh.codec, sh.binary
            )
        }),
        Truth::Ambiguous => None,
    }
}
/// Rule 1: the explicit choice persists independently of the decode result.
fn choice_problem(sh: &Shown, persist: Option<&str>) -> Option<String> {
    let want = persist.map(canon);
    let got = sh.preferred.as_deref().map(canon);
    if sh.chosen != want.is_some() || (want.is_some() && got != want) {
        Some(format!(
            "CHOICE expected persistent {:?}, got chosen={} preferred={:?}",
            persist, sh.chosen, sh.preferred
        ))
    } else {
        None
    }
}
fn check(sh: &Shown, e: &Exp, persist: Option<&str>) -> Option<String> {
    let decoded = match e {
        Exp::Binary => {
            (!sh.binary).then(|| format!("expected hex, got {:?} {}", sh.text, sh.codec))
        }
        Exp::Replaced { text, codec } | Exp::Text { text, codec, .. } => {
            if sh.binary {
                Some(format!("expected {text:?} {codec}, got hex view"))
            } else if sh.text != *text || sh.codec != *codec {
                Some(format!(
                    "expected {text:?} {codec}, got {:?} {}",
                    sh.text, sh.codec
                ))
            } else {
                None
            }
        }
    };
    decoded.or_else(|| choice_problem(sh, persist))
}
struct Obs {
    loading_seen: bool,
    prefixes: Vec<String>,
}
impl Obs {
    fn new() -> Self {
        Self {
            loading_seen: false,
            prefixes: vec![],
        }
    }
}
fn frame(a: &mut App) {
    a.workspace.poll();
    // Lane B publishes failed-load recovery through the App's non-modal queue.
    // Mirror the native frame instead of inspecting an undrained status queue.
    a.publish_resource_reports();
    let viewport = a.viewport();
    a.panels.poll(&mut a.workspace, viewport);
    a.sync_active_view();
}
fn pump(a: &mut App, obs: &mut Obs, ready: impl Fn(&App) -> bool) -> bool {
    let deadline = Instant::now() + Duration::from_secs(20);
    loop {
        frame(a);
        let t = &a.workspace.tabs[a.workspace.active];
        if t.loading.is_some() {
            obs.loading_seen = true;
        }
        let p: String = a
            .workspace
            .editor()
            .text
            .chunks()
            .next()
            .map(|c| c.chars().take(48).collect())
            .unwrap_or_default();
        if obs.prefixes.last() != Some(&p) {
            obs.prefixes.push(p);
        }
        if ready(a) {
            for _ in 0..3 {
                frame(a);
            }
            return true;
        }
        if Instant::now() > deadline {
            return false;
        }
        std::thread::park_timeout(Duration::from_millis(2));
    }
}
fn idle(a: &App) -> bool {
    let t = &a.workspace.tabs[a.workspace.active];
    t.loading.is_none() && t.binary_loading.is_none()
}
fn modal(a: &App) -> Vec<String> {
    let mut v = vec![];
    if !a.workspace.messages.is_empty() {
        v.push(format!("MODAL messages {:?}", a.workspace.messages));
    }
    if a.panels.overlay.is_some() {
        v.push(format!("MODAL overlay {:?}", a.panels.overlay));
    }
    v
}
fn mk(fallback: &str, bg: bool) -> (App, tempfile::TempDir) {
    let prof = tempfile::tempdir().unwrap();
    let mut a = app("", "Plain Text", Some(prof.path()));
    a.workspace
        .settings
        .set(Layer::User, "fallback_encoding", json!(fallback));
    a.workspace.settings.set(
        Layer::User,
        "large_file.load_bytes",
        json!(if bg { 1 } else { 64 * 1024 * 1024 }),
    );
    a.workspace.watcher = Some(vel_fileio::Watcher::new().unwrap());
    (a, prof)
}
fn mtime(p: &Path) -> SystemTime {
    std::fs::metadata(p).unwrap().modified().unwrap()
}
fn set_mtime(p: &Path, t: SystemTime) {
    std::fs::File::open(p).unwrap().set_modified(t).unwrap();
}
/// External write (or touch when `bytes` is None) followed by watcher-driven reload.
fn external(a: &mut App, path: &Path, bytes: Option<&[u8]>, obs: &mut Obs) -> bool {
    let m = mtime(path) + Duration::from_secs(2);
    if let Some(b) = bytes {
        std::fs::write(path, b).unwrap();
    }
    set_mtime(path, m);
    pump(a, obs, |a| {
        let t = &a.workspace.tabs[a.workspace.active];
        idle(a) && t.disk_stamp.is_some_and(|(_, time)| time == m)
    })
}
fn open(a: &mut App, path: &Path, obs: &mut Obs) -> Result<(), String> {
    let r = a.run_named_depth(None, "open_file", &json!({"file": path}), 0);
    if a.workspace.tabs[a.workspace.active].loading.is_some() {
        obs.loading_seen = true;
    }
    if !pump(a, obs, idle) {
        return Err("open timeout".into());
    }
    r
}
fn edit(a: &mut App, text: &str) {
    let len = a.workspace.editor().text.len_bytes();
    a.workspace.editor_mut().set_caret(len, false);
    input(a, text);
    frame(a);
}
fn cmd(a: &mut App, name: &str, args: Value) -> Result<(), String> {
    let r = a.run_named_depth(None, name, &args, 0);
    let mut o = Obs::new();
    pump(a, &mut o, idle);
    r
}
fn session_file(prof: &Path) -> PathBuf {
    prof.join("Sessions/Session.sublime-session")
}
/// Real checkpoint -> JSON on disk -> vel_session::load -> restore_window.
fn restart(
    a: &mut App,
    prof: &Path,
    fallback: &str,
    bg: bool,
    history: bool,
    between: impl FnOnce(),
) -> Result<(App, tempfile::TempDir), String> {
    if !history {
        a.workspace
            .settings
            .set(Layer::User, "hot_exit", json!("disabled"));
    }
    a.save_workspace_checkpoint()?;
    if !history {
        a.workspace
            .settings
            .set(Layer::User, "hot_exit", json!("always"));
    }
    between();
    restore_from(&session_file(prof), fallback, bg)
}
fn restore_from(file: &Path, fallback: &str, bg: bool) -> Result<(App, tempfile::TempDir), String> {
    let rec = vel_session::load(file);
    if !rec.messages.is_empty() {
        return Err(format!("session load: {:?}", rec.messages));
    }
    let (mut b, prof) = mk(fallback, bg);
    let w = rec.session.windows.first().ok_or("no window")?.clone();
    b.workspace.restore_window(&w, &rec.session.documents)?;
    let mut o = Obs::new();
    if !pump(&mut b, &mut o, idle) {
        return Err("restore timeout".into());
    }
    Ok((b, prof))
}
fn line_text(text: &str, a: &App) -> String {
    let t = &a.workspace.tabs[a.workspace.active];
    text.replace('\n', t.format.line_ending.as_str())
}

// ---------------------------------------------------------------- states
#[derive(Clone, Copy, Debug)]
enum St {
    Auto,
    Chosen(&'static str),
    Fallback(usize),
    SavedFallback(usize),
    DirtyAuto,
    DirtyChosen,
    SavedWithEnc(&'static str),
    HotClean(Option<&'static str>),
    HotDirty,
    NoHist(&'static str),
    Main(&'static str),
}
// (choice, base text, external bytes that fail the choice, fallback codec)
fn fallbacks(k: usize) -> (&'static str, &'static str, Vec<u8>, &'static str) {
    match k {
        0 => (
            SJIS,
            "日本語ベース\n",
            "日本語 ✓ done\n".as_bytes().to_vec(),
            "UTF-8",
        ),
        1 => (
            U8,
            "base naïve ✓\n",
            b"caf\xe9 ok\n".to_vec(),
            "windows-1252",
        ),
        3 => (
            SJIS,
            "日本語ベース\n",
            "naïve café ✓!".as_bytes().to_vec(),
            "UTF-8",
        ),
        _ => (U16LE, "base text\n", b"odd!\n".to_vec(), "UTF-8"),
    }
}
fn base_for(choice: &str) -> (&'static str, Vec<u8>) {
    match choice {
        SJIS => (
            "日本語ベース\n",
            enc("日本語ベース\n", SJIS, false).unwrap(),
        ),
        U8 => ("base naïve ✓\n", "base naïve ✓\n".as_bytes().to_vec()),
        W1252 => ("base café\n", enc("base café\n", W1252, false).unwrap()),
        U16LE => ("base text\n", enc("base text\n", U16LE, false).unwrap()),
        GBK => ("中文基础\n", enc("中文基础\n", GBK, false).unwrap()),
        _ => ("base text\n", b"base text\n".to_vec()),
    }
}
struct Cell {
    a: App,
    prof: tempfile::TempDir,
    _dir: tempfile::TempDir,
    path: PathBuf,
    /// The user's original explicit choice (oracle).
    choice: Option<&'static str>,
    /// Diagnostic only (never accepted): fallback codec a plain save wrote, or the
    /// main-format revision hint.
    accepted: Option<String>,
    /// Main-format user's reopen choice before the session round-trip (rule 4: dropped).
    main_choice: Option<&'static str>,
    /// Text expected after one undo, if the history holds an edit.
    undo_to: Option<String>,
    fallback: &'static str,
}
fn main_fixtures() -> &'static Path {
    static FIXTURES: std::sync::OnceLock<tempfile::TempDir> = std::sync::OnceLock::new();
    FIXTURES
        .get_or_init(|| {
            let dir = tempfile::tempdir().unwrap();
            macro_rules! put {
                ($case:literal) => {{
                    let folder = dir.path().join($case);
                    std::fs::create_dir_all(&folder).unwrap();
                    std::fs::write(
                        folder.join("session.json"),
                        include_bytes!(concat!(
                            "fixtures/main-385dcdd-matrix/",
                            $case,
                            "/session.json"
                        )),
                    )
                    .unwrap();
                    std::fs::write(
                        folder.join("doc.txt"),
                        include_bytes!(concat!("fixtures/main-385dcdd-matrix/", $case, "/doc.txt")),
                    )
                    .unwrap();
                    std::fs::write(
                        folder.join("encoding.txt"),
                        include_bytes!(concat!(
                            "fixtures/main-385dcdd-matrix/",
                            $case,
                            "/encoding.txt"
                        )),
                    )
                    .unwrap();
                    std::fs::write(
                        folder.join("expected.txt"),
                        include_bytes!(concat!(
                            "fixtures/main-385dcdd-matrix/",
                            $case,
                            "/expected.txt"
                        )),
                    )
                    .unwrap();
                }};
            }
            put!("cp1252_chosen_clean");
            put!("cp1252_clean");
            put!("cp1252_dirty");
            put!("gbk_clean");
            put!("sjis_clean");
            put!("sjis_dirty");
            put!("utf16le_bom_clean");
            put!("utf16le_bom_dirty");
            put!("utf16le_clean");
            put!("utf8_bom_dirty");
            put!("utf8_clean");
            put!("utf8_dirty");
            dir
        })
        .path()
}
fn main_case(case: &str) -> (Option<&'static str>, PathBuf) {
    let choice = match case {
        "sjis_clean" | "sjis_dirty" => Some(SJIS),
        "gbk_clean" => Some(GBK),
        "cp1252_chosen_clean" => Some(W1252),
        _ => None,
    };
    (choice, main_fixtures().join(case))
}
fn build(st: St, fallback: &'static str, bg: bool) -> Result<Cell, String> {
    let dir = tempfile::tempdir().unwrap();
    let path = std::fs::canonicalize(dir.path()).unwrap().join("doc.txt");
    let mut o = Obs::new();
    match st {
        St::Main(case) => {
            let (choice, src) = main_case(case);
            let original = std::fs::read_to_string(src.join("session.json")).unwrap();
            let original_value: Value = serde_json::from_str(&original).unwrap();
            let old = original_value["documents"][0]["path"].as_str().unwrap();
            let json = original.replace(old, path.to_str().unwrap());
            std::fs::copy(src.join("doc.txt"), &path).unwrap();
            let v: serde_json::Value = serde_json::from_str(&json).unwrap();
            if let Some(ns) = v["documents"][0]["disk"]["modified_ns"].as_u64() {
                set_mtime(&path, SystemTime::UNIX_EPOCH + Duration::from_nanos(ns));
            }
            let file = dir.path().join("main.sublime-session");
            std::fs::write(&file, json).unwrap();
            let (a, prof) = restore_from(&file, fallback, bg)?;
            let legacy = std::fs::read_to_string(src.join("encoding.txt")).unwrap();
            let dirty = case.ends_with("dirty");
            let undo_to = dirty.then(|| {
                let e = std::fs::read_to_string(src.join("expected.txt")).unwrap();
                e[..e.rfind('\n').unwrap() + 1].to_string()
            });
            return Ok(Cell {
                a,
                prof,
                _dir: dir,
                path,
                choice: None,
                accepted: Some(legacy),
                main_choice: choice,
                undo_to,
                fallback,
            });
        }
        St::HotClean(choice) => {
            let mut c = build(choice.map_or(St::Auto, St::Chosen), fallback, bg)?;
            let (a, prof) = restart(&mut c.a, c.prof.path(), fallback, bg, true, || {})?;
            c.a = a;
            c.prof = prof;
            return Ok(c);
        }
        St::HotDirty => {
            let mut c = build(St::DirtyChosen, fallback, bg)?;
            let (a, prof) = restart(&mut c.a, c.prof.path(), fallback, bg, true, || {})?;
            c.a = a;
            c.prof = prof;
            return Ok(c);
        }
        St::NoHist(choice) => {
            let mut c = build(St::Chosen(choice), fallback, bg)?;
            let (a, prof) = restart(&mut c.a, c.prof.path(), fallback, bg, false, || {})?;
            c.a = a;
            c.prof = prof;
            return Ok(c);
        }
        _ => {}
    }
    let (mut a, prof) = mk(fallback, bg);
    let mut cell_choice = None;
    let mut accepted = None;
    let mut undo_to = None;
    match st {
        St::Auto | St::DirtyAuto | St::SavedWithEnc(_) => {
            let text = if matches!(st, St::SavedWithEnc(_)) {
                "base text\n"
            } else {
                "base naïve text\n"
            };
            std::fs::write(&path, text).unwrap();
            open(&mut a, &path, &mut o)?;
            if let St::SavedWithEnc(e) = st {
                cmd(&mut a, "save", json!({"encoding": e}))?;
                cell_choice = Some(e);
            }
            if matches!(st, St::DirtyAuto) {
                undo_to = Some(a.workspace.editor().text.to_string());
                edit(&mut a, "+d");
            }
        }
        St::Chosen(_) | St::DirtyChosen | St::Fallback(_) | St::SavedFallback(_) => {
            let choice = match st {
                St::Chosen(c) => c,
                St::DirtyChosen => SJIS,
                St::Fallback(k) | St::SavedFallback(k) => fallbacks(k).0,
                _ => unreachable!(),
            };
            let (text, bytes) = base_for(choice);
            std::fs::write(&path, &bytes).unwrap();
            open(&mut a, &path, &mut o)?;
            cmd(&mut a, "reopen", json!({"encoding": choice}))?;
            if a.workspace.editor().text != text
                || !a.workspace.tabs[a.workspace.active].encoding_chosen
            {
                return Err(format!("setup reopen {choice}: {:?}", shown(&a)));
            }
            cell_choice = Some(choice);
            if let St::Fallback(k) | St::SavedFallback(k) = st {
                let (_, _, bytes, codec) = fallbacks(k);
                if !external(&mut a, &path, Some(&bytes), &mut o) {
                    return Err("setup fallback timeout".into());
                }
                let sh = shown(&a);
                // Choice persistence is checked per cell (rule 1), not as a setup error.
                if sh.codec != codec {
                    return Err(format!("setup fallback: {sh:?}"));
                }
                if matches!(st, St::SavedFallback(3)) {
                    // Exact finding-A repro: delete " ✓!" and save.
                    let len = a.workspace.editor().text.len_bytes();
                    a.workspace.editor_mut().set_caret(len, false);
                    for _ in 0..3 {
                        cmd(&mut a, "left_delete", json!({}))?;
                    }
                    if a.workspace.editor().text != "naïve café" {
                        return Err(format!("repro A delete: {:?}", shown(&a)));
                    }
                    cmd(&mut a, "save", json!({}))?;
                    accepted = Some(codec.to_string());
                } else if matches!(st, St::SavedFallback(_)) {
                    undo_to = Some(sh.text.clone());
                    edit(&mut a, "+e");
                    cmd(&mut a, "save", json!({}))?;
                    accepted = Some(codec.to_string());
                }
            }
            if matches!(st, St::DirtyChosen) {
                undo_to = Some(a.workspace.editor().text.to_string());
                edit(&mut a, "+d");
            }
        }
        _ => unreachable!(),
    }
    let m = modal(&a);
    if !m.is_empty() {
        return Err(format!("setup modal {m:?}"));
    }
    Ok(Cell {
        a,
        prof,
        _dir: dir,
        path,
        choice: cell_choice,
        accepted,
        main_choice: None,
        undo_to,
        fallback,
    })
}
fn st_name(st: St) -> String {
    format!("{st:?}")
        .replace([' ', '"', '(', ')'], "")
        .replace("JapaneseShiftJIS", "SJIS")
        .replace("WesternWindows1252", "W1252")
}
fn main_states() -> Vec<St> {
    [
        "utf8_clean",
        "cp1252_clean",
        "sjis_clean",
        "gbk_clean",
        "utf16le_clean",
        "utf16le_bom_clean",
        "cp1252_chosen_clean",
        "sjis_dirty",
        "utf8_dirty",
        "cp1252_dirty",
    ]
    .into_iter()
    .map(St::Main)
    .collect()
}

// ---------------------------------------------------------------- cells
/// External rewrite with each sample, then restart with/without native history.
fn rewrite_cells(rep: &mut Rep, st: St, samples: &[Sample]) {
    let mut fg_notices: std::collections::BTreeMap<&'static str, String> = Default::default();
    for bg in [false, true] {
        for smp in samples {
            let id = format!(
                "{}|{}|rewrite|{}",
                st_name(st),
                smp.name,
                if bg { "bg" } else { "fg" }
            );
            let mut c = match build(st, W1252, bg) {
                Ok(c) => c,
                Err(e) => {
                    rep.cell(&id, vec![format!("SETUP {e}")]);
                    continue;
                }
            };
            let before = shown(&c.a);
            let disk_before = std::fs::read(&c.path).unwrap();
            c.a.panels.set_message(String::new());
            let mut o = Obs::new();
            let mut p = vec![];
            if !external(&mut c.a, &c.path, Some(&smp.bytes), &mut o) {
                rep.cell(&id, vec!["TIMEOUT reload".into()]);
                continue;
            }
            let sh = shown(&c.a);
            p.extend(modal(&c.a));
            let exp = oracle(&smp.bytes, c.choice, c.fallback, false);
            let alt = c
                .accepted
                .as_deref()
                .map(|acc| oracle(&smp.bytes, Some(acc), c.fallback, false));
            let strict_rule = oracle(&smp.bytes, c.choice, c.fallback, true);
            if strict_rule != exp {
                rep.note(
                    &id,
                    format!("NUL-OVERRIDE claimed {exp:?} vs explicit-rule {strict_rule:?}"),
                );
            }
            let tab = &c.a.workspace.tabs[c.a.workspace.active];
            let same_bytes = disk_before == smp.bytes;
            let message = c.a.panels.message.clone();
            let dir = c.path.parent().unwrap().display().to_string();
            let notice = message.replace(&dir, "<dir>");
            if bg {
                if let Some(fg) = fg_notices.get(smp.name)
                    && *fg != notice
                {
                    p.push(format!("NOTICE differs fg {fg:?} vs bg {notice:?}"));
                }
            } else {
                fg_notices.insert(smp.name, notice);
            }
            // Text the user ends up seeing for this revision (live or conflict payload).
            let mut seen = sh.clone();
            if before.dirty {
                if sh.text != before.text {
                    p.push(format!(
                        "dirty text replaced: {:?} -> {:?}",
                        before.text, sh.text
                    ));
                }
                match &tab.external {
                    Some(loaded) => {
                        seen.text = loaded.text.to_string();
                        seen.codec = loaded.format.encoding.clone();
                        seen.binary = false;
                        if matches!(exp, Exp::Binary) {
                            p.push("binary rewrite offered as text conflict".into());
                        }
                    }
                    None => {
                        if !same_bytes && !matches!(exp, Exp::Binary) {
                            p.push("dirty: no conflict for real change".into());
                        }
                        seen = before.clone();
                    }
                }
            } else if tab.external.is_some() {
                p.push("MODAL conflict on clean tab".into());
            }
            let named = message.contains("doc.txt");
            // Dirty tabs keep their edits on a binary rewrite (notice only); clean tabs enter hex.
            let binary_reload = matches!(exp, Exp::Binary)
                && before.dirty
                && !seen.binary
                && (seen.text == before.text)
                && message.contains("binary file")
                && named;
            let mismatch = if same_bytes {
                (seen != before)
                    .then(|| format!("RULE2 identical bytes changed state {before:?} -> {seen:?}"))
            } else {
                match &exp {
                    Exp::Binary => {
                        if !(seen.binary || binary_reload) {
                            Some(format!(
                                "expected hex view, got {:?} bin={} notice {message:?}",
                                seen.text, seen.binary
                            ))
                        } else if !(message.contains("binary file") && named) {
                            Some(format!("binary notice missing: {message:?}"))
                        } else {
                            choice_problem(&sh, c.choice)
                        }
                    }
                    _ if before.dirty && tab.external.is_none() => choice_problem(&sh, c.choice),
                    _ => check(&seen, &exp, c.choice),
                }
            };
            if let Some(err) = mismatch {
                let rule_ok = !same_bytes
                    && strict_rule != exp
                    && match &strict_rule {
                        Exp::Text { text, codec, .. } => {
                            !seen.binary && seen.text == *text && seen.codec == *codec
                        }
                        _ => false,
                    };
                let alt_ok = alt.as_ref().is_some_and(|alt| match alt {
                    Exp::Text { text, codec, .. } | Exp::Replaced { text, codec } => {
                        !seen.binary && seen.text == *text && seen.codec == *codec
                    }
                    Exp::Binary => seen.binary || binary_reload,
                });
                if rule_ok && choice_problem(&sh, c.choice).is_none() {
                    rep.note(&id, format!("NUL-rule divergence: {err}"));
                } else {
                    p.push(format!(
                        "POLICY {err}{}",
                        if alt_ok {
                            " [matches diagnostic accepted/legacy codec]"
                        } else {
                            ""
                        }
                    ));
                }
            }
            if let Exp::Replaced { .. } = &exp
                && !same_bytes
                && !before.dirty
                && !(named && message.contains("replacement"))
            {
                p.push(format!("replacement notice missing: {message:?}"));
            }
            if !before.dirty
                && let Exp::Text { codec, .. } = &exp
                && !seen.binary
                && seen.codec == *codec
                && let Some(choice) = c.choice
                && canon(choice) != *codec
                && !same_bytes
                && !named
            {
                p.push(format!("override notice missing: {message:?}"));
            }
            if let Some(mc) = c.main_choice
                && !same_bytes
                && oracle(&smp.bytes, Some(mc), c.fallback, false) != exp
            {
                rep.note(
                    &id,
                    format!(
                        "RULE4 main-format reopen choice {mc} not honored (expected by rule 4)"
                    ),
                );
            }
            if !(binary_reload || same_bytes || (before.dirty && tab.external.is_none()))
                && let Some(m) = mojibake(&seen, smp, c.choice, c.fallback)
            {
                p.push(m);
            }
            if bg
                && !o.loading_seen
                && !matches!(exp, Exp::Binary)
                && !before.binary
                && !before.dirty
            {
                rep.note(&id, "bg load not observed".into());
            }
            rep.cell(&id, p);
            // Restart with and without native history.
            for history in [true, false] {
                if !history && before.dirty {
                    continue;
                }
                let rid = format!("{id}|restart|hist={history}");
                let pre = shown(&c.a);
                let mut q = vec![];
                match restart(&mut c.a, c.prof.path(), c.fallback, bg, history, || {}) {
                    Err(e) => q.push(format!("restart error {e}")),
                    Ok((b, _p)) => {
                        let post = shown(&b);
                        q.extend(modal(&b));
                        if pre.dirty {
                            if post.binary || post.text != pre.text || !post.dirty {
                                q.push(format!("dirty restart changed {:?} -> {:?}", pre, post));
                            }
                        } else if matches!(exp, Exp::Binary) && pre.binary {
                            if !post.binary {
                                q.push(format!("binary disk restored as text {:?}", post.text));
                            }
                        } else if post.text != pre.text
                            || post.codec != pre.codec
                            || post.dirty != pre.dirty
                            || post.binary != pre.binary
                        {
                            q.push(format!("restart changed {:?} -> {:?}", pre, post));
                        }
                        if post.chosen != pre.chosen
                            || post.preferred.as_deref().map(canon)
                                != pre.preferred.as_deref().map(canon)
                        {
                            q.push(format!(
                                "CHOICE changed by restart {:?}/{:?} -> {:?}/{:?}",
                                pre.chosen, pre.preferred, post.chosen, post.preferred
                            ));
                        }
                        if !pre.dirty
                            && !post.binary
                            && let Some(m) = mojibake(&post, smp, c.choice, c.fallback)
                        {
                            q.push(m);
                        }
                    }
                }
                rep.cell(&rid, q);
            }
        }
    }
}
/// Touch (raw bytes identical) while open, while open and dirty, and while closed.
fn touch_cells(rep: &mut Rep, st: St) {
    for bg in [false, true] {
        for variant in ["open", "open-dirty", "closed", "open-then-restart"] {
            let id = format!(
                "{}|touch-{variant}|{}",
                st_name(st),
                if bg { "bg" } else { "fg" }
            );
            let mut c = match build(st, W1252, bg) {
                Ok(c) => c,
                Err(e) => {
                    rep.cell(&id, vec![format!("SETUP {e}")]);
                    continue;
                }
            };
            if variant == "open-dirty" {
                c.undo_to = Some(c.a.workspace.editor().text.to_string());
                edit(&mut c.a, "+t");
            }
            let before = shown(&c.a);
            let sel_before = c.a.workspace.editor().caret;
            c.a.panels.set_message(String::new());
            let mut p = vec![];
            let mut o = Obs::new();
            let path = c.path.clone();
            let mut restarted: Option<App> = None;
            if variant == "closed" {
                match restart(&mut c.a, c.prof.path(), c.fallback, bg, true, || {
                    let m = mtime(&path) + Duration::from_secs(2);
                    set_mtime(&path, m);
                }) {
                    Ok((b, prof)) => {
                        c.prof = prof;
                        restarted = Some(b);
                    }
                    Err(e) => {
                        rep.cell(&id, vec![format!("restart {e}")]);
                        continue;
                    }
                }
            } else {
                if !external(&mut c.a, &c.path, None, &mut o) {
                    rep.cell(&id, vec!["TIMEOUT touch".into()]);
                    continue;
                }
                let t = &c.a.workspace.tabs[c.a.workspace.active];
                if t.external.is_some() {
                    p.push("MODAL conflict on touch".into());
                }
                if c.a.panels.message.contains("doc.txt") {
                    p.push(format!("notice on touch: {:?}", c.a.panels.message));
                }
                if c.a.workspace.editor().caret != sel_before {
                    p.push("caret moved by touch".into());
                }
                if variant == "open-then-restart" {
                    match restart(&mut c.a, c.prof.path(), c.fallback, bg, true, || {}) {
                        Ok((b, prof)) => {
                            c.prof = prof;
                            restarted = Some(b);
                        }
                        Err(e) => {
                            rep.cell(&id, vec![format!("restart {e}")]);
                            continue;
                        }
                    }
                }
            }
            let target: &mut App = match restarted.as_mut() {
                Some(b) => b,
                None => &mut c.a,
            };
            let after = shown(target);
            p.extend(modal(target));
            if after != before {
                p.push(format!("touch changed state {before:?} -> {after:?}"));
            }
            if let Some(u) = &c.undo_to {
                let _ = cmd(target, "undo", json!({}));
                let t = target.workspace.editor().text.to_string();
                if t != *u {
                    p.push(format!("UNDO lost: after undo {t:?}, expected {u:?}"));
                }
            }
            rep.cell(&id, p);
        }
    }
}
/// Save after an edit, then Save with each encoding, then touch and restart.
fn save_cells(rep: &mut Rep, st: St) {
    for bg in [false, true] {
        let mut encs: Vec<Option<&str>> = vec![None];
        encs.extend(SAVE_ENCS.iter().copied().map(Some));
        for e in encs {
            let id = format!(
                "{}|save-{}|{}",
                st_name(st),
                e.unwrap_or("after-edit"),
                if bg { "bg" } else { "fg" }
            );
            let mut c = match build(st, W1252, bg) {
                Ok(c) => c,
                Err(err) => {
                    rep.cell(&id, vec![format!("SETUP {err}")]);
                    continue;
                }
            };
            if c.a.workspace.tabs[c.a.workspace.active]
                .editor
                .binary
                .is_some()
            {
                continue;
            }
            let mut p = vec![];
            let disk_before = std::fs::read(&c.path).unwrap();
            if e.is_none() {
                edit(&mut c.a, "+s");
            }
            let text = c.a.workspace.editor().text.to_string();
            let fmt_before = c.a.workspace.tabs[c.a.workspace.active].format.clone();
            let choice_before = {
                let sh = shown(&c.a);
                (sh.chosen, sh.preferred.clone())
            };
            let r = cmd(
                &mut c.a,
                "save",
                e.map_or(json!({}), |e| json!({"encoding": e})),
            );
            let (codec, bom) = match e {
                Some(e) => (canon(e), e.ends_with("with BOM")),
                None => (fmt_before.encoding.clone(), fmt_before.bom),
            };
            let expected = enc(&line_text(&text, &c.a), &codec, bom);
            let disk = std::fs::read(&c.path).unwrap();
            match (&r, &expected) {
                (Ok(()), Some(x)) => {
                    if disk != *x {
                        p.push(format!("SAVE bytes {:02x?} != {:02x?}", disk, x));
                    }
                    let sh = shown(&c.a);
                    if sh.dirty || sh.codec != codec || sh.text != text {
                        p.push(format!("after save {sh:?}"));
                    }
                    if let Some(e) = e {
                        if let Some(err) = choice_problem(&sh, Some(e)) {
                            p.push(format!("save-with-encoding: {err}"));
                        }
                    } else if sh.chosen != choice_before.0
                        || sh.preferred.as_deref().map(canon)
                            != choice_before.1.as_deref().map(canon)
                    {
                        p.push(format!(
                            "RULE1 plain save changed choice {:?} -> {}/{:?}",
                            choice_before, sh.chosen, sh.preferred
                        ));
                    }
                }
                (Err(err), None) => {
                    if disk != disk_before {
                        p.push(format!("failed save modified disk ({err})"));
                    }
                    if c.a.workspace.tabs[c.a.workspace.active].format != fmt_before {
                        p.push("failed save changed format".into());
                    }
                    rep.cell(&id, p);
                    continue;
                }
                (Ok(()), None) => {
                    let overlay = c.a.panels.overlay;
                    if disk != disk_before
                        || !matches!(overlay, Some(crate::panels::Overlay::Choices))
                        || c.a.workspace.tabs[c.a.workspace.active].format != fmt_before
                        || !c.a.workspace.messages.is_empty()
                    {
                        p.push(format!(
                            "unrepresentable save: disk {:02x?} overlay {overlay:?}",
                            disk
                        ));
                    }
                    rep.cell(&id, p);
                    continue;
                }
                (Err(err), Some(_)) => p.push(format!("save failed: {err}")),
            }
            p.extend(modal(&c.a));
            // Touch: unchanged, undo intact.
            let before = shown(&c.a);
            let mut o = Obs::new();
            if !external(&mut c.a, &c.path, None, &mut o) {
                p.push("TIMEOUT touch".into());
            } else {
                let after = shown(&c.a);
                if after != before {
                    p.push(format!("touch after save changed {before:?} -> {after:?}"));
                }
                if c.a.workspace.tabs[c.a.workspace.active].external.is_some() {
                    p.push("MODAL conflict on touch after save".into());
                }
            }
            // Restart with history: same text/codec; then undo works for the edit variant.
            match restart(&mut c.a, c.prof.path(), c.fallback, bg, true, || {}) {
                Err(err) => p.push(format!("restart {err}")),
                Ok((mut b, _prof)) => {
                    let post = shown(&b);
                    if post.text != before.text || post.codec != before.codec || post.dirty {
                        p.push(format!("restart after save {before:?} -> {post:?}"));
                    }
                    if post.chosen != before.chosen
                        || post.preferred.as_deref().map(canon)
                            != before.preferred.as_deref().map(canon)
                    {
                        p.push(format!(
                            "CHOICE changed by restart after save {before:?} -> {post:?}"
                        ));
                    }
                    p.extend(modal(&b));
                    if e.is_none() {
                        let _ = cmd(&mut b, "undo", json!({}));
                        let t = b.workspace.editor().text.to_string();
                        if !text.ends_with("+s") || t != text[..text.len() - 2] {
                            p.push(format!("UNDO after restart: {t:?}"));
                        }
                    }
                }
            }
            rep.cell(&id, p);
        }
    }
}
/// Reopen with each encoding on the state's current file.
fn reopen_cells(rep: &mut Rep, st: St) {
    for e in REOPEN_ENCS {
        let id = format!("{}|reopen-{e}", st_name(st));
        let mut c = match build(st, W1252, false) {
            Ok(c) => c,
            Err(err) => {
                rep.cell(&id, vec![format!("SETUP {err}")]);
                continue;
            }
        };
        let before = shown(&c.a);
        if before.dirty {
            // Requires the native unsaved-changes confirmation; not headless.
            continue;
        }
        let bytes = std::fs::read(&c.path).unwrap();
        c.a.panels.set_message(String::new());
        let r = cmd(&mut c.a, "reopen", json!({"encoding": e}));
        let mut p = vec![];
        let sh = shown(&c.a);
        p.extend(modal(&c.a));
        let exp = oracle(&bytes, Some(e), c.fallback, false);
        let msg = c.a.panels.message.clone();
        match (&r, &exp) {
            (Err(err), _) => p.push(format!("reopen error (modal in GUI): {err}")),
            (Ok(()), Exp::Binary) => {
                if !sh.binary || !(msg.contains("binary file") && msg.contains("doc.txt")) {
                    p.push(format!(
                        "binary reopen not hex+notice: bin={} {:?} {msg:?}",
                        sh.binary, sh.text
                    ));
                }
                if let Some(err) = choice_problem(&sh, Some(e)) {
                    p.push(err);
                }
            }
            (Ok(()), _) => {
                if let Some(err) = check(&sh, &exp, Some(e)) {
                    let strict_rule = oracle(&bytes, Some(e), c.fallback, true);
                    if strict_rule != exp && check(&sh, &strict_rule, Some(e)).is_none() {
                        rep.note(&id, format!("NUL-rule divergence: {err}"));
                    } else {
                        p.push(format!("POLICY {err}"));
                    }
                }
                let notice_needed = match &exp {
                    Exp::Text { chosen, .. } => !chosen,
                    Exp::Replaced { .. } => true,
                    Exp::Binary => false,
                };
                if notice_needed && !msg.contains("doc.txt") {
                    p.push(format!("override notice missing {msg:?}"));
                }
            }
        }
        rep.cell(&id, p);
    }
}
fn state_matrix(name: &str, states: Vec<St>) {
    let mut rep = Rep::new(name);
    let samples = samples();
    for st in states {
        rewrite_cells(&mut rep, st, &samples);
        touch_cells(&mut rep, st);
        save_cells(&mut rep, st);
        reopen_cells(&mut rep, st);
    }
}

