fn r20_matrix_main_restore_shows_main_text() {
    let mut rep = Rep::new("main_restore");
    for st in main_states() {
        let St::Main(case) = st else { unreachable!() };
        let src = main_fixtures().join(case);
        let expected = std::fs::read_to_string(src.join("expected.txt")).unwrap();
        let legacy = std::fs::read_to_string(src.join("encoding.txt")).unwrap();
        for bg in [false, true] {
            let id = format!("{case}|main-restore|{}", if bg { "bg" } else { "fg" });
            match build(st, W1252, bg) {
                Err(e) => rep.cell(&id, vec![format!("restore error {e}")]),
                Ok(c) => {
                    let sh = shown(&c.a);
                    let mut p = modal(&c.a);
                    if case == "utf16le_clean" {
                        // Main's binary placeholder had no retained text. The
                        // bounded UTF-16 detector now recovers the actual document.
                        if sh.text != "hello utf16 text\n" || sh.codec != "UTF-16LE" || sh.binary {
                            p.push(format!("BOM-less UTF-16 restored incorrectly: {sh:?}"));
                        }
                    } else if sh.text != expected || sh.codec != legacy {
                        p.push(format!(
                            "main showed {expected:?} {legacy}; restored {sh:?}"
                        ));
                    }
                    if sh.dirty != case.ends_with("dirty") {
                        p.push(format!("dirty flag {sh:?}"));
                    }
                    if let Some(err) = choice_problem(&sh, None) {
                        p.push(format!("RULE4 {err}"));
                    }
                    rep.cell(&id, p);
                }
            }
        }
    }
}
