#[ignore = "independent decode-policy matrix"]
fn r20_matrix_open_matrix() {
    let mut rep = Rep::new("open");
    for smp in samples() {
        for fallback in [W1252, SJIS] {
            for bg in [false, true] {
                let id = format!(
                    "open|{}|fb={fallback}|{}",
                    smp.name,
                    if bg { "bg" } else { "fg" }
                );
                let dir = tempfile::tempdir().unwrap();
                let path = std::fs::canonicalize(dir.path()).unwrap().join("doc.txt");
                std::fs::write(&path, &smp.bytes).unwrap();
                let (mut a, _prof) = mk(fallback, bg);
                a.panels.set_message(String::new());
                let mut o = Obs::new();
                let r = open(&mut a, &path, &mut o);
                let exp = oracle(&smp.bytes, None, fallback, false);
                let sh = shown(&a);
                let mut p = modal(&a);
                let msg = a.panels.message.clone();
                match (&r, &exp) {
                    (Err(e), _) => p.push(format!("open error {e}")),
                    (Ok(()), _) => {
                        if let Some(err) = check(&sh, &exp, None) {
                            p.push(format!("POLICY {err}"));
                        }
                        if let Some(m) = mojibake(&sh, &smp, None, fallback) {
                            p.push(m);
                        }
                        match &exp {
                            Exp::Replaced { .. }
                                if !(msg.contains("doc.txt") && msg.contains("replacement")) =>
                            {
                                p.push(format!("replacement notice missing {msg:?}"))
                            }
                            Exp::Binary
                                if !(msg.contains("doc.txt") && msg.contains("binary file")) =>
                            {
                                p.push(format!("binary notice missing {msg:?}"))
                            }
                            _ => {}
                        }
                    }
                }
                if bg && !matches!(exp, Exp::Binary) && r.is_ok() && !o.loading_seen {
                    rep.note(&id, "bg not observed".into());
                }
                rep.cell(&id, p);
            }
        }
    }
}
