#[ignore = "independent decode-policy matrix"]
fn r20_matrix_reopen_each_sample() {
    let mut rep = Rep::new("reopen_samples");
    for smp in samples() {
        for e in REOPEN_ENCS {
            let id = format!("reopen|{}|{e}", smp.name);
            let dir = tempfile::tempdir().unwrap();
            let path = std::fs::canonicalize(dir.path()).unwrap().join("doc.txt");
            std::fs::write(&path, &smp.bytes).unwrap();
            let (mut a, prof) = mk(W1252, false);
            let mut o = Obs::new();
            if let Err(err) = open(&mut a, &path, &mut o) {
                rep.note(&id, format!("open failed {err}"));
                continue;
            }
            let before = shown(&a);
            a.panels.set_message(String::new());
            let r = cmd(&mut a, "reopen", json!({"encoding": e}));
            let sh = shown(&a);
            let mut p = modal(&a);
            let exp = oracle(&smp.bytes, Some(e), W1252, false);
            match (&r, &exp) {
                (Err(err), _) => p.push(format!("reopen error (modal in GUI): {err}")),
                (Ok(()), Exp::Binary) => {
                    let _ = &before;
                    if !sh.binary
                        || !(a.panels.message.contains("binary file")
                            && a.panels.message.contains("doc.txt"))
                    {
                        p.push(format!(
                            "binary reopen not hex+notice {sh:?} {:?}",
                            a.panels.message
                        ));
                    }
                    if let Some(err) = choice_problem(&sh, Some(e)) {
                        p.push(err);
                    }
                }
                (Ok(()), _) => {
                    if let Some(err) = check(&sh, &exp, Some(e)) {
                        let strict_rule = oracle(&smp.bytes, Some(e), W1252, true);
                        if strict_rule != exp && check(&sh, &strict_rule, Some(e)).is_none() {
                            rep.note(&id, format!("NUL-rule divergence: {err}"));
                        } else {
                            p.push(format!("POLICY {err}"));
                        }
                    }
                    if let Some(m) = mojibake(&sh, &smp, Some(e), W1252) {
                        p.push(m);
                    }
                    if matches!(exp, Exp::Text { chosen: false, .. } | Exp::Replaced { .. })
                        && !a.panels.message.contains("doc.txt")
                    {
                        p.push(format!("override notice missing {:?}", a.panels.message));
                    }
                    if sh.preferred.as_deref() != Some(*e) {
                        p.push(format!("preference not retained: {:?}", sh.preferred));
                    }
                }
            }
            // Restart (fg and bg): same view of the bytes.
            for bg in [false, true] {
                match restart(&mut a, prof.path(), W1252, bg, true, || {}) {
                    Err(err) => p.push(format!("restart {err}")),
                    Ok((b, _)) => {
                        let post = shown(&b);
                        p.extend(modal(&b));
                        if post.binary != sh.binary
                            || (!sh.binary && (post.text != sh.text || post.codec != sh.codec))
                            || post.chosen != sh.chosen
                            || post.preferred != sh.preferred
                        {
                            p.push(format!("restart bg={bg} {sh:?} -> {post:?}"));
                        }
                    }
                }
            }
            rep.cell(&id, p);
        }
    }
}
#[test]
#[ignore = "independent decode-policy matrix"]
fn r20_matrix_save_with_encoding_texts() {
    let mut rep = Rep::new("save_texts");
    let texts = [
        ("ascii", "plain ascii\n"),
        ("latin", "naïve café\n"),
        ("ja", "日本語かな\n"),
        ("zh", "中文简体字\n"),
        ("ko", "한국어\n"),
        ("emoji", "ok 😀\n"),
        ("ar", "مرحبا\n"),
        ("euro", "€ “q”\n"),
    ];
    for (tn, text) in texts {
        for e in SAVE_ENCS {
            for bg in [false, true] {
                let id = format!("savetext|{tn}|{e}|{}", if bg { "bg" } else { "fg" });
                let dir = tempfile::tempdir().unwrap();
                let path = std::fs::canonicalize(dir.path()).unwrap().join("doc.txt");
                std::fs::write(&path, text).unwrap();
                let (mut a, prof) = mk(W1252, bg);
                let mut o = Obs::new();
                if let Err(err) = open(&mut a, &path, &mut o) {
                    rep.cell(&id, vec![format!("open {err}")]);
                    continue;
                }
                let mut p = vec![];
                let r = cmd(&mut a, "save", json!({"encoding": e}));
                let x = enc(text, e, e.ends_with("with BOM"));
                let disk = std::fs::read(&path).unwrap();
                match (&r, &x) {
                    (Ok(()), Some(x)) => {
                        if disk != *x {
                            p.push(format!("SAVE bytes {disk:02x?} != {x:02x?}"));
                        }
                    }
                    (Err(_), None) => {
                        if disk != text.as_bytes() {
                            p.push("failed save changed disk".into());
                        }
                        rep.cell(&id, p);
                        continue;
                    }
                    (Ok(()), None) => {
                        if disk != text.as_bytes()
                            || !matches!(a.panels.overlay, Some(crate::panels::Overlay::Choices))
                            || !a.workspace.messages.is_empty()
                        {
                            p.push(format!(
                                "unrepresentable save: disk {disk:02x?} overlay {:?}",
                                a.panels.overlay
                            ));
                        }
                        rep.cell(&id, p);
                        continue;
                    }
                    (Err(err), Some(_)) => p.push(format!("save failed {err}")),
                }
                // Save after edit in the chosen encoding.
                edit(&mut a, "Z");
                let r2 = cmd(&mut a, "save", json!({}));
                let disk2 = std::fs::read(&path).unwrap();
                let x2 = enc(&format!("{text}Z"), e, e.ends_with("with BOM"));
                if r2.is_err() || x2.as_ref().is_some_and(|x2| *x2 != disk2) {
                    p.push(format!("save after edit {r2:?} {disk2:02x?}"));
                }
                // Touch, undo intact.
                let before = shown(&a);
                if !external(&mut a, &path, None, &mut o) {
                    p.push("TIMEOUT touch".into());
                } else if shown(&a) != before
                    || a.workspace.tabs[a.workspace.active].external.is_some()
                {
                    p.push(format!("touch changed {:?} -> {:?}", before, shown(&a)));
                }
                // External rewrite in the same codec, then restart.
                let t3 = format!("{text}ZW");
                if let Some(bytes) = enc(&t3, e, e.ends_with("with BOM")) {
                    if !external(&mut a, &path, Some(&bytes), &mut o) {
                        p.push("TIMEOUT rewrite".into());
                    } else {
                        let sh = shown(&a);
                        if sh.text != t3 || sh.codec != canon(e) || !sh.chosen {
                            p.push(format!("rewrite in chosen codec showed {sh:?}"));
                        }
                    }
                }
                let pre = shown(&a);
                match restart(&mut a, prof.path(), W1252, bg, true, || {}) {
                    Err(err) => p.push(format!("restart {err}")),
                    Ok((b, _)) => {
                        let post = shown(&b);
                        if post.text != pre.text
                            || post.codec != pre.codec
                            || post.chosen != pre.chosen
                        {
                            p.push(format!("restart {pre:?} -> {post:?}"));
                        }
                    }
                }
                p.extend(modal(&a));
                rep.cell(&id, p);
            }
        }
    }
}
/// Speculative last-effective decode must not publish a provisional mojibake prefix.
#[test]
#[ignore = "independent decode-policy matrix"]
fn r20_matrix_background_restore_transient_prefix() {
    let mut rep = Rep::new("transient");
    for (name, original, replacement, truth_prefix) in [
        (
            "w1252-effective-then-utf8",
            enc(&"caf\u{e9} cr\u{e8}me\n".repeat(400_000), W1252, false).unwrap(),
            "naïve café ✓\n".repeat(400_000).into_bytes(),
            "naïve café ✓",
        ),
        (
            "sjis-chosen-then-utf8",
            enc(&"日本語かな\n".repeat(400_000), SJIS, false).unwrap(),
            "日本語 ✓ done\n".repeat(400_000).into_bytes(),
            "日本語 ✓ done",
        ),
    ] {
        let id = format!("transient|{name}");
        let dir = tempfile::tempdir().unwrap();
        let path = std::fs::canonicalize(dir.path()).unwrap().join("doc.txt");
        std::fs::write(&path, &original).unwrap();
        let (mut a, prof) = mk(W1252, false);
        let mut o = Obs::new();
        if open(&mut a, &path, &mut o).is_err() {
            rep.cell(&id, vec!["open".into()]);
            continue;
        }
        if name.starts_with("sjis") {
            let _ = cmd(&mut a, "reopen", json!({"encoding": SJIS}));
        }
        let mut p = vec![];
        let r = restart(&mut a, prof.path(), W1252, true, true, || {
            std::fs::write(&path, &replacement).unwrap();
        });
        let _ = r.as_ref().map(|_| ());
        // Restart helper pumps internally; repeat manually to observe prefixes.
        let rec = vel_session::load(&session_file(prof.path()));
        let (mut b, _p2) = mk(W1252, true);
        b.workspace
            .restore_window(&rec.session.windows[0], &rec.session.documents)
            .unwrap();
        let mut o = Obs::new();
        pump(&mut b, &mut o, idle);
        let bad: Vec<_> = o
            .prefixes
            .iter()
            .filter(|x| {
                !x.is_empty()
                    && !truth_prefix.starts_with(x.as_str())
                    && !x.starts_with(truth_prefix)
            })
            .cloned()
            .collect();
        let final_text = b
            .workspace
            .editor()
            .text
            .chunks()
            .next()
            .map(|c| c.chars().take(20).collect::<String>())
            .unwrap_or_default();
        if !bad.is_empty() {
            p.push(format!(
                "TRANSIENT MOJIBAKE prefixes {:?}",
                bad.iter().take(3).collect::<Vec<_>>()
            ));
        }
        if !final_text.starts_with(truth_prefix) {
            p.push(format!("final {final_text:?}"));
        }
        rep.note(&id, format!("observed prefixes {}", o.prefixes.len()));
        rep.cell(&id, p);
    }
}
#[test]
#[ignore = "independent decode-policy matrix"]
fn r20_matrix_mixed_line_endings_and_keep_edits() {
    let mut rep = Rep::new("mixed_crlf");
    let crlf = b"a\r\nb\r\nc\r\n".to_vec();
    let one_lf = b"a\r\nb\nc\r\n".to_vec();
    for bg in [false, true] {
        for dirty in [false, true] {
            for (label, from, to) in [
                ("crlf->onelf", crlf.clone(), one_lf.clone()),
                ("onelf->crlf", one_lf.clone(), crlf.clone()),
            ] {
                let id = format!(
                    "mixed|{label}|dirty={dirty}|{}",
                    if bg { "bg" } else { "fg" }
                );
                let dir = tempfile::tempdir().unwrap();
                let path = std::fs::canonicalize(dir.path()).unwrap().join("doc.txt");
                std::fs::write(&path, &from).unwrap();
                let (mut a, _prof) = mk(W1252, bg);
                let mut o = Obs::new();
                let mut p = vec![];
                if let Err(e) = open(&mut a, &path, &mut o) {
                    rep.cell(&id, vec![format!("open {e}")]);
                    continue;
                }
                if dirty {
                    edit(&mut a, "x");
                }
                let before = shown(&a);
                if !external(&mut a, &path, Some(&to), &mut o) {
                    rep.cell(&id, vec!["TIMEOUT".into()]);
                    continue;
                }
                let t = &a.workspace.tabs[a.workspace.active];
                if dirty {
                    if t.external.is_none() {
                        p.push("one line-ending change behind dirty tab: no conflict".into());
                    }
                } else {
                    if t.external.is_some() {
                        p.push("MODAL conflict on clean tab".into());
                    }
                    let sh = shown(&a);
                    if sh.text != "a\nb\nc\n" || sh.dirty {
                        p.push(format!("clean reload {sh:?}"));
                    }
                }
                p.extend(modal(&a));
                if dirty {
                    // Keep Edits, then an unchanged touch: ask again?
                    a.workspace.reload_external(a.workspace.active, false);
                    if !external(&mut a, &path, None, &mut o) {
                        p.push("TIMEOUT touch".into());
                    } else if a.workspace.tabs[a.workspace.active].external.is_some() {
                        p.push("after Keep Edits, an unchanged touch re-prompts (modal)".into());
                    }
                    if shown(&a).text != before.text {
                        p.push("dirty text lost".into());
                    }
                } else {
                    // Identity follows the new bytes: a touch is quiet.
                    let pre = shown(&a);
                    if !external(&mut a, &path, None, &mut o) {
                        p.push("TIMEOUT touch".into());
                    } else if shown(&a) != pre
                        || a.workspace.tabs[a.workspace.active].external.is_some()
                    {
                        p.push("touch after line-ending reload changed state".into());
                    }
                }
                rep.cell(&id, p);
            }
        }
    }
}
/// Restored but inactive (lazy) sheets decode through the same policy on activation.
#[test]
#[ignore = "independent decode-policy matrix"]
fn r20_matrix_lazy_inactive_tabs() {
    let mut rep = Rep::new("lazy");
    for st in [
        St::Chosen(SJIS),
        St::Chosen(U16LE),
        St::Fallback(3),
        St::SavedFallback(3),
        St::SavedFallback(1),
        St::DirtyChosen,
        St::SavedWithEnc("UTF-16 LE with BOM"),
        St::HotClean(Some(SJIS)),
        St::Main("sjis_clean"),
        St::Main("cp1252_clean"),
        St::Main("sjis_dirty"),
    ] {
        for bg in [false, true] {
            for touched in [false, true] {
                let id = format!(
                    "{}|lazy|touched={touched}|{}",
                    st_name(st),
                    if bg { "bg" } else { "fg" }
                );
                let mut c = match build(st, W1252, bg) {
                    Ok(c) => c,
                    Err(e) => {
                        rep.cell(&id, vec![format!("SETUP {e}")]);
                        continue;
                    }
                };
                let pre = shown(&c.a);
                let other = c.path.parent().unwrap().join("other.txt");
                std::fs::write(&other, "other\n").unwrap();
                let mut o = Obs::new();
                let mut p = vec![];
                if let Err(e) = open(&mut c.a, &other, &mut o) {
                    rep.cell(&id, vec![format!("open other {e}")]);
                    continue;
                }
                let path = c.path.clone();
                match restart(&mut c.a, c.prof.path(), c.fallback, bg, true, || {
                    if touched {
                        let m = mtime(&path) + Duration::from_secs(2);
                        set_mtime(&path, m);
                    }
                }) {
                    Err(e) => p.push(format!("restart {e}")),
                    Ok((mut b, _prof)) => {
                        let index = b
                            .workspace
                            .tabs
                            .iter()
                            .position(|t| t.path.as_deref() == Some(path.as_path()));
                        match index {
                            None => p.push("lazy tab missing".into()),
                            Some(index) => {
                                if b.workspace.tabs[index].lazy.is_none() {
                                    rep.note(&id, "tab was not lazy".into());
                                }
                                b.workspace.select(index);
                                let mut o = Obs::new();
                                pump(&mut b, &mut o, idle);
                                let post = shown(&b);
                                p.extend(modal(&b));
                                if post.text != pre.text
                                    || post.codec != pre.codec
                                    || post.chosen != pre.chosen
                                    || post.dirty != pre.dirty
                                {
                                    p.push(format!("lazy activation {pre:?} -> {post:?}"));
                                }
                                if let Some(u) = &c.undo_to {
                                    let _ = cmd(&mut b, "undo", json!({}));
                                    let t = b.workspace.editor().text.to_string();
                                    if t != *u {
                                        p.push(format!(
                                            "UNDO lost in lazy tab: {t:?} expected {u:?}"
                                        ));
                                    }
                                }
                            }
                        }
                    }
                }
                rep.cell(&id, p);
            }
        }
    }
}
/// A terminal background-restore failure must not leave a stale identity behind.
#[test]
#[ignore = "independent decode-policy matrix"]
fn r20_matrix_failed_background_restore_recovers() {
    use std::os::unix::fs::PermissionsExt;
    let mut rep = Rep::new("failed_restore");
    for st in [St::Auto, St::Chosen(SJIS), St::SavedFallback(3)] {
        for history in [true, false] {
            let id = format!("{}|failed-bg-restore|hist={history}", st_name(st));
            let mut c = match build(st, W1252, true) {
                Ok(c) => c,
                Err(e) => {
                    rep.cell(&id, vec![format!("SETUP {e}")]);
                    continue;
                }
            };
            let pre = shown(&c.a);
            let path = c.path.clone();
            let mut p = vec![];
            let restored = restart(&mut c.a, c.prof.path(), c.fallback, true, history, || {
                std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o000)).unwrap();
            });
            std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o644)).unwrap();
            match restored {
                Err(e) => p.push(format!("restore error (modal in GUI?): {e}")),
                Ok((mut b, _prof)) => {
                    p.extend(modal(&b));
                    let failed = shown(&b);
                    rep.note(
                        &id,
                        format!(
                            "after failed load: text {:?} read_only {} notice {:?}",
                            failed.text,
                            b.workspace.editor().read_only,
                            b.panels.message
                        ),
                    );
                    let mut o = Obs::new();
                    if !external(&mut b, &path, None, &mut o) {
                        p.push("TIMEOUT recovery touch".into());
                    } else {
                        let post = shown(&b);
                        p.extend(modal(&b));
                        if post.text != pre.text
                            || post.codec != pre.codec
                            || post.dirty
                            || b.workspace.editor().read_only
                        {
                            p.push(format!(
                                "not recovered: {pre:?} -> {post:?} ro={}",
                                b.workspace.editor().read_only
                            ));
                        }
                    }
                }
            }
            rep.cell(&id, p);
        }
    }
}

// ---------------------------------------------------------------- verify4 additions
struct PermGuard(PathBuf);
impl Drop for PermGuard {
    fn drop(&mut self) {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&self.0, std::fs::Permissions::from_mode(0o644));
    }
}
fn ensure_fails(choice: &str, text: &str) -> Option<Vec<u8>> {
    // UTF-8 detour bytes that the explicit choice cannot decode strictly.
    for extra in ["", "!", "!!", " \u{1f600}", " \u{1f600}!"] {
        let b = format!("{text}{extra}").into_bytes();
        if strict(choice, &b).is_none() && std::str::from_utf8(&b).is_ok() && !b.contains(&0) {
            return Some(b);
        }
    }
    None
}
/// Rule 1/2: a plain save after an explicit choice (directly, or after a fallback
/// revision) never changes the choice; a later rewrite in the choice's encoding decodes
/// with it, also after restart with and without native history.
#[test]
#[ignore = "independent decode-policy matrix"]
fn r20_matrix_plain_save_after_choice_then_rewrite() {
    let mut rep = Rep::new("plain_save_choice");
    let cases: &[(&str, &str, &str, &str)] = &[
        (SJIS, "jp", "日本語ベース\n", "日本語かな変更\n"),
        (SJIS, "ascii", "日本語ベース\n", "ascii only rewrite\n"),
        (GBK, "zh", "中文基础\n", "中文简体字改写\n"),
        (W1252, "w1252", "base café\n", "réécrit “ok” €\n"),
        (EUCKR, "ko", "한국어 기본\n", "한국어 다시 작성\n"),
        (L1, "latin1", "base café\n", "naïve façade\n"),
        (U16LE, "u16-cjk", "base text\n", "rewritten 日本語\n"),
        (U16LE, "u16-ascii", "base text\n", "rewritten ascii\n"),
    ];
    for &(choice, kind, base, rewrite) in cases {
        for via in ["reopen", "save_with_encoding", "set_encoding"] {
            for detour in [false, true] {
                for bg in [false, true] {
                    let id = format!(
                        "plainsave|{}|{kind}|via={via}|detour={detour}|{}",
                        canon(choice),
                        if bg { "bg" } else { "fg" }
                    );
                    let detour_bytes = ensure_fails(choice, "detour ✓ naïve\n");
                    if detour && detour_bytes.is_none() {
                        rep.note(
                            &id,
                            format!("{choice} decodes any UTF-8 detour; not applicable"),
                        );
                        continue;
                    }
                    let dir = tempfile::tempdir().unwrap();
                    let path = std::fs::canonicalize(dir.path()).unwrap().join("doc.txt");
                    let (mut a, prof) = mk(W1252, bg);
                    let mut o = Obs::new();
                    let mut p = vec![];
                    // 1. Establish the explicit choice.
                    let setup: Result<(), String> = (|| {
                        match via {
                            "reopen" => {
                                std::fs::write(&path, enc(base, choice, false).unwrap()).unwrap();
                                open(&mut a, &path, &mut o)?;
                                cmd(&mut a, "reopen", json!({"encoding": choice}))?;
                            }
                            "save_with_encoding" => {
                                std::fs::write(&path, base).unwrap();
                                open(&mut a, &path, &mut o)?;
                                cmd(&mut a, "save", json!({"encoding": choice}))?;
                            }
                            _ => {
                                std::fs::write(&path, base).unwrap();
                                open(&mut a, &path, &mut o)?;
                                cmd(&mut a, "set_encoding", json!({"encoding": choice}))?;
                                cmd(&mut a, "save", json!({}))?;
                            }
                        }
                        Ok(())
                    })();
                    if let Err(e) = setup {
                        rep.cell(&id, vec![format!("SETUP {e}")]);
                        continue;
                    }
                    let sh = shown(&a);
                    if sh.text != base || sh.codec != canon(choice) || sh.dirty {
                        p.push(format!("setup state {sh:?}"));
                    }
                    if std::fs::read(&path).unwrap() != enc(base, choice, false).unwrap() {
                        p.push(format!("setup disk {:02x?}", std::fs::read(&path).unwrap()));
                    }
                    if let Some(e) = choice_problem(&sh, Some(choice)) {
                        p.push(format!("setup {e}"));
                    }
                    // 2. Optional fallback revision (choice cannot decode it).
                    let mut fmt_codec = canon(choice);
                    if detour {
                        let b = detour_bytes.clone().unwrap();
                        a.panels.set_message(String::new());
                        if !external(&mut a, &path, Some(&b), &mut o) {
                            rep.cell(&id, vec!["TIMEOUT detour".into()]);
                            continue;
                        }
                        let sh = shown(&a);
                        if sh.codec != "UTF-8" || sh.text != norm(std::str::from_utf8(&b).unwrap())
                        {
                            p.push(format!("detour decode {sh:?}"));
                        }
                        if !a.panels.message.contains("doc.txt") {
                            p.push(format!("detour notice missing {:?}", a.panels.message));
                        }
                        if let Some(e) = choice_problem(&sh, Some(choice)) {
                            p.push(format!("RULE1 fallback promoted: {e}"));
                        }
                        fmt_codec = "UTF-8".into();
                    }
                    // 3. Edit + plain save.
                    edit(&mut a, "+e");
                    let text = a.workspace.editor().text.to_string();
                    if let Err(e) = cmd(&mut a, "save", json!({})) {
                        p.push(format!("plain save failed {e}"));
                    }
                    let disk = std::fs::read(&path).unwrap();
                    if Some(&disk) != enc(&text, &fmt_codec, false).as_ref() {
                        p.push(format!("plain save bytes ({fmt_codec}) {disk:02x?}"));
                    }
                    let sh = shown(&a);
                    if let Some(e) = choice_problem(&sh, Some(choice)) {
                        p.push(format!("RULE1 plain save: {e}"));
                    }
                    // 4. External rewrite in the choice's encoding.
                    let bytes = enc(rewrite, choice, false).unwrap();
                    a.panels.set_message(String::new());
                    if !external(&mut a, &path, Some(&bytes), &mut o) {
                        rep.cell(&id, vec!["TIMEOUT rewrite".into()]);
                        continue;
                    }
                    let sh = shown(&a);
                    p.extend(modal(&a));
                    if a.workspace.tabs[a.workspace.active].external.is_some() {
                        p.push("MODAL conflict on clean tab".into());
                    }
                    if sh.binary || sh.text != rewrite || sh.codec != canon(choice) || sh.dirty {
                        p.push(format!(
                            "REWRITE expected {rewrite:?} {}, got {sh:?}",
                            canon(choice)
                        ));
                    }
                    if let Some(e) = choice_problem(&sh, Some(choice)) {
                        p.push(format!("rewrite {e}"));
                    }
                    // 5. Touch: unchanged.
                    if !external(&mut a, &path, None, &mut o) {
                        p.push("TIMEOUT touch".into());
                    } else if shown(&a) != sh
                        || a.workspace.tabs[a.workspace.active].external.is_some()
                    {
                        p.push(format!("touch changed {sh:?} -> {:?}", shown(&a)));
                    }
                    rep.cell(&format!("{id}|rewrite"), p);
                    // 6. Restart with/without history, then another rewrite in the choice codec.
                    for history in [true, false] {
                        let rid = format!("{id}|restart|hist={history}");
                        let mut q = vec![];
                        match restart(&mut a, prof.path(), W1252, bg, history, || {}) {
                            Err(e) => q.push(format!("restart error {e}")),
                            Ok((mut b, _p)) => {
                                let post = shown(&b);
                                q.extend(modal(&b));
                                if post != sh {
                                    q.push(format!("restart changed {sh:?} -> {post:?}"));
                                }
                                let again = format!("{rewrite}2\n");
                                let bytes = enc(&again, choice, false).unwrap();
                                let mut o = Obs::new();
                                if !external(&mut b, &path, Some(&bytes), &mut o) {
                                    q.push("TIMEOUT rewrite after restart".into());
                                } else {
                                    let s2 = shown(&b);
                                    if s2.binary || s2.text != again || s2.codec != canon(choice) {
                                        q.push(format!("REWRITE after restart expected {again:?} {}, got {s2:?}", canon(choice)));
                                    }
                                    if let Some(e) = choice_problem(&s2, Some(choice)) {
                                        q.push(format!("after restart {e}"));
                                    }
                                }
                                // Put the previous bytes back for the next history variant.
                                std::fs::write(&path, enc(rewrite, choice, false).unwrap())
                                    .unwrap();
                                let m = mtime(&path) + Duration::from_secs(4);
                                set_mtime(&path, m);
                                let mut o = Obs::new();
                                pump(&mut a, &mut o, |a| {
                                    let t = &a.workspace.tabs[a.workspace.active];
                                    idle(a) && t.disk_stamp.is_some_and(|(_, time)| time == m)
                                });
                            }
                        }
                        rep.cell(&rid, q);
                    }
                }
            }
        }
    }
}

/// "Keep Edits" acknowledges the external identity: an unchanged touch is quiet,
/// a real change prompts again; the kept text stays unsaved and undoable.
#[test]
#[ignore = "independent decode-policy matrix"]
fn r20_matrix_keep_edits_then_touch() {
    let mut rep = Rep::new("keep_edits");
    let states = [
        St::Auto,
        St::Chosen(SJIS),
        St::Chosen(U16LE),
        St::Fallback(0),
        St::SavedFallback(1),
        St::HotDirty,
        St::Main("sjis_dirty"),
        St::Main("utf8_dirty"),
        St::Main("cp1252_dirty"),
    ];
    for st in states {
        for change in ["text", "line-endings", "other-codec"] {
            for bg in [false, true] {
                for tail in ["touch", "restart", "save", "realchange"] {
                    let id = format!(
                        "{}|keep-{change}|{tail}|{}",
                        st_name(st),
                        if bg { "bg" } else { "fg" }
                    );
                    let mut c = match build(st, W1252, bg) {
                        Ok(c) => c,
                        Err(e) => {
                            rep.cell(&id, vec![format!("SETUP {e}")]);
                            continue;
                        }
                    };
                    if !shown(&c.a).dirty {
                        c.undo_to = Some(c.a.workspace.editor().text.to_string());
                        edit(&mut c.a, "+k");
                    }
                    let before = shown(&c.a);
                    let disk = std::fs::read(&c.path).unwrap();
                    let codec = c.a.workspace.tabs[c.a.workspace.active]
                        .saved_format
                        .encoding
                        .clone();
                    let external_bytes = match change {
                        "text" => {
                            let t = format!(
                                "{}external\n",
                                c.a.workspace.tabs[c.a.workspace.active]
                                    .editor
                                    .buffer
                                    .text()
                                    .slice(0..0)
                            );
                            let base = std::fs::read(&c.path).unwrap();
                            let mut b = base.clone();
                            let extra =
                                enc(&t, &codec, false).unwrap_or_else(|| t.clone().into_bytes());
                            b.extend(extra);
                            b
                        }
                        "line-endings" => {
                            let mut b = Vec::new();
                            // Same text, CRLF (single-byte LF codecs only; UTF-16 uses its own units).
                            if codec.starts_with("UTF-16") {
                                let s = vel_fileio::encoding(&codec)
                                    .unwrap()
                                    .decode_without_bom_handling(&disk)
                                    .0
                                    .replace('\n', "\r\n");
                                b = enc(&s, &codec, false).unwrap();
                            } else {
                                for &x in &disk {
                                    if x == b'\n' {
                                        b.push(b'\r');
                                    }
                                    b.push(x);
                                }
                            }
                            b
                        }
                        _ => "ext ✓ utf8 only\n".as_bytes().to_vec(),
                    };
                    if external_bytes == disk {
                        rep.note(&id, "external bytes identical; skipped".into());
                        continue;
                    }
                    let mut p = vec![];
                    let mut o = Obs::new();
                    c.a.panels.set_message(String::new());
                    if !external(&mut c.a, &c.path, Some(&external_bytes), &mut o) {
                        rep.cell(&id, vec!["TIMEOUT rewrite".into()]);
                        continue;
                    }
                    let active = c.a.workspace.active;
                    if c.a.workspace.tabs[active].external.is_none() {
                        p.push(format!(
                            "no conflict for real change behind dirty tab ({change})"
                        ));
                        rep.cell(&id, p);
                        continue;
                    }
                    // Keep Edits.
                    c.a.workspace.reload_external(active, false);
                    frame(&mut c.a);
                    let kept = shown(&c.a);
                    if kept.text != before.text || !kept.dirty || kept.binary {
                        p.push(format!(
                            "KEEP changed live text/dirty {before:?} -> {kept:?}"
                        ));
                    }
                    if kept.chosen != before.chosen || kept.preferred != before.preferred {
                        p.push(format!("KEEP changed choice {before:?} -> {kept:?}"));
                    }
                    p.extend(modal(&c.a));
                    match tail {
                        "touch" => {
                            for n in 0..2 {
                                if !external(&mut c.a, &c.path, None, &mut o) {
                                    p.push("TIMEOUT touch".into());
                                    break;
                                }
                                if c.a.workspace.tabs[active].external.is_some() {
                                    p.push(format!(
                                        "KEEP-TOUCH unchanged touch #{n} re-prompts (modal)"
                                    ));
                                    c.a.workspace.reload_external(active, false);
                                }
                                if shown(&c.a) != kept {
                                    p.push(format!(
                                        "touch #{n} changed {kept:?} -> {:?}",
                                        shown(&c.a)
                                    ));
                                }
                            }
                            if let Some(u) = &c.undo_to {
                                let _ = cmd(&mut c.a, "undo", json!({}));
                                let t = c.a.workspace.editor().text.to_string();
                                if t != *u {
                                    p.push(format!("UNDO after keep: {t:?} expected {u:?}"));
                                }
                                if !c.a.workspace.tabs[active].dirty() {
                                    p.push("after Keep + undo to old disk text the tab reports clean (disk differs)".into());
                                }
                            }
                        }
                        "realchange" => {
                            let mut b = external_bytes.clone();
                            b.extend(
                                enc("more\n", &codec, false).unwrap_or_else(|| b"more\n".to_vec()),
                            );
                            if codec.starts_with("UTF-16") && b.len() % 2 == 1 {
                                b.push(0);
                            }
                            if !external(&mut c.a, &c.path, Some(&b), &mut o) {
                                p.push("TIMEOUT realchange".into());
                            } else if c.a.workspace.tabs[active].external.is_none() {
                                p.push("after Keep, a real change no longer prompts".into());
                            }
                            if shown(&c.a).text != kept.text {
                                p.push("realchange replaced kept text".into());
                            }
                        }
                        "save" => {
                            let text = c.a.workspace.editor().text.to_string();
                            let fmt = c.a.workspace.tabs[active].format.clone();
                            match cmd(&mut c.a, "save", json!({})) {
                                Err(e) => p.push(format!("save after keep failed: {e}")),
                                Ok(()) => {
                                    let disk = std::fs::read(&c.path).unwrap();
                                    let x = enc(&line_text(&text, &c.a), &fmt.encoding, fmt.bom);
                                    if x.as_ref() != Some(&disk) {
                                        p.push(format!(
                                            "save after keep wrote {disk:02x?}, expected {x:02x?}"
                                        ));
                                    }
                                    let sh = shown(&c.a);
                                    if sh.dirty
                                        || sh.chosen != before.chosen
                                        || sh.preferred != before.preferred
                                    {
                                        p.push(format!("after save {sh:?}"));
                                    }
                                    if !external(&mut c.a, &c.path, None, &mut o) {
                                        p.push("TIMEOUT touch".into());
                                    } else if c.a.workspace.tabs[active].external.is_some()
                                        || shown(&c.a) != sh
                                    {
                                        p.push("touch after keep+save not quiet".into());
                                    }
                                }
                            }
                        }
                        _ => {
                            // Hot exit, touch while closed, restore: dirty text, no prompt, undo.
                            let path = c.path.clone();
                            match restart(&mut c.a, c.prof.path(), c.fallback, bg, true, || {
                                let m = mtime(&path) + Duration::from_secs(2);
                                set_mtime(&path, m);
                            }) {
                                Err(e) => p.push(format!("restart {e}")),
                                Ok((mut b, _prof)) => {
                                    let post = shown(&b);
                                    p.extend(modal(&b));
                                    if post.text != kept.text
                                        || !post.dirty
                                        || post.chosen != kept.chosen
                                    {
                                        p.push(format!("restart after keep {kept:?} -> {post:?}"));
                                    }
                                    let mut o = Obs::new();
                                    if !external(&mut b, &path, None, &mut o) {
                                        p.push("TIMEOUT touch after restart".into());
                                    } else if b.workspace.tabs[b.workspace.active]
                                        .external
                                        .is_some()
                                    {
                                        p.push("KEEP-TOUCH after restart: unchanged touch re-prompts (modal)".into());
                                    }
                                    if let Some(u) = &c.undo_to {
                                        let _ = cmd(&mut b, "undo", json!({}));
                                        let t = b.workspace.editor().text.to_string();
                                        if t != *u {
                                            p.push(format!(
                                                "UNDO after keep+restart: {t:?} expected {u:?}"
                                            ));
                                        }
                                    }
                                }
                            }
                        }
                    }
                    rep.cell(&id, p);
                }
            }
        }
    }
}

/// Unreadable at restore: non-modal, watched placeholder; never writes; recovers
/// (text, codec, choice, dirty, undo) after chmod back + touch.
#[test]
#[ignore = "independent decode-policy matrix"]
fn r20_matrix_unreadable_restore_recovers() {
    use std::os::unix::fs::PermissionsExt;
    let mut rep = Rep::new("unreadable_restore");
    let states = [
        St::Auto,
        St::Chosen(SJIS),
        St::Chosen(U16LE),
        St::Fallback(0),
        St::SavedFallback(3),
        St::SavedWithEnc(SJIS),
        St::DirtyChosen,
        St::Main("sjis_clean"),
        St::Main("cp1252_clean"),
        St::Main("sjis_dirty"),
    ];
    for st in states {
        for history in [true, false] {
            for bg in [false, true] {
                for lazy in [false, true] {
                    for mode in [0o000u32, 0o200] {
                        for rehot in [false, true] {
                            let id = format!(
                                "{}|unreadable|hist={history}|{}|lazy={lazy}|mode={mode:o}|rehot={rehot}",
                                st_name(st),
                                if bg { "bg" } else { "fg" }
                            );
                            let mut c = match build(st, W1252, bg) {
                                Ok(c) => c,
                                Err(e) => {
                                    rep.cell(&id, vec![format!("SETUP {e}")]);
                                    continue;
                                }
                            };
                            let pre = shown(&c.a);
                            if pre.dirty && !history {
                                continue;
                            }
                            let path = c.path.clone();
                            let _guard = PermGuard(path.clone());
                            let disk = std::fs::read(&path).unwrap();
                            let mut p = vec![];
                            if lazy {
                                let other = path.parent().unwrap().join("other.txt");
                                std::fs::write(&other, "other\n").unwrap();
                                let mut o = Obs::new();
                                if let Err(e) = open(&mut c.a, &other, &mut o) {
                                    rep.cell(&id, vec![format!("open other {e}")]);
                                    continue;
                                }
                            }
                            let restored =
                                restart(&mut c.a, c.prof.path(), c.fallback, bg, history, || {
                                    std::fs::set_permissions(
                                        &path,
                                        std::fs::Permissions::from_mode(mode),
                                    )
                                    .unwrap();
                                });
                            let (mut b, mut prof) = match restored {
                                Err(e) => {
                                    rep.cell(
                                        &id,
                                        vec![format!("restore error (modal in GUI?): {e}")],
                                    );
                                    continue;
                                }
                                Ok(x) => x,
                            };
                            let index = b
                                .workspace
                                .tabs
                                .iter()
                                .position(|t| t.path.as_deref() == Some(path.as_path()));
                            let Some(index) = index else {
                                rep.cell(&id, vec!["tab missing after restore".into()]);
                                continue;
                            };
                            if lazy {
                                b.workspace.select(index);
                                let mut o = Obs::new();
                                pump(&mut b, &mut o, idle);
                            }
                            if rehot {
                                // Hot-exit again while still unreadable: the placeholder must not
                                // replace the retained revision/history.
                                match restart(&mut b, prof.path(), c.fallback, bg, true, || {}) {
                                    Err(e) => {
                                        rep.cell(&id, vec![format!("second restore error {e}")]);
                                        continue;
                                    }
                                    Ok((b2, p2)) => {
                                        b = b2;
                                        prof = p2;
                                    }
                                }
                                let index = b
                                    .workspace
                                    .tabs
                                    .iter()
                                    .position(|t| t.path.as_deref() == Some(path.as_path()))
                                    .unwrap();
                                b.workspace.select(index);
                                let mut o = Obs::new();
                                pump(&mut b, &mut o, idle);
                            }
                            let _ = &prof;
                            let failed = shown(&b);
                            p.extend(modal(&b));
                            let msg = b.panels.message.clone();
                            if pre.dirty {
                                if failed.text != pre.text || !failed.dirty {
                                    p.push(format!(
                                        "dirty edits not retained while unreadable: {failed:?}"
                                    ));
                                }
                            } else {
                                if !b.workspace.editor().read_only {
                                    p.push(format!("placeholder not read-only: {failed:?}"));
                                }
                                if !(msg.contains("doc.txt") || rehot) {
                                    p.push(format!("no file-named status notice: {msg:?}"));
                                }
                                rep.note(
                                    &id,
                                    format!("placeholder text {:?} notice {msg:?}", failed.text),
                                );
                            }
                            // Save on the placeholder must not overwrite the file.
                            if !pre.dirty {
                                let _ = cmd(&mut b, "save", json!({}));
                                std::fs::set_permissions(
                                    &path,
                                    std::fs::Permissions::from_mode(0o644),
                                )
                                .unwrap();
                                if std::fs::read(&path).unwrap() != disk {
                                    p.push(
                                        "SAVE on unreadable placeholder overwrote the file".into(),
                                    );
                                    std::fs::write(&path, &disk).unwrap();
                                }
                            } else {
                                std::fs::set_permissions(
                                    &path,
                                    std::fs::Permissions::from_mode(0o644),
                                )
                                .unwrap();
                            }
                            p.extend(modal(&b));
                            let mut o = Obs::new();
                            if !external(&mut b, &path, None, &mut o) {
                                p.push("TIMEOUT recovery touch".into());
                            } else {
                                let post = shown(&b);
                                p.extend(modal(&b));
                                if b.workspace.tabs[b.workspace.active].external.is_some() {
                                    p.push("recovery prompts a conflict (modal)".into());
                                }
                                if post.text != pre.text
                                    || post.codec != pre.codec
                                    || post.dirty != pre.dirty
                                    || post.chosen != pre.chosen
                                    || post.preferred != pre.preferred
                                    || post.binary != pre.binary
                                    || b.workspace.editor().read_only
                                {
                                    p.push(format!(
                                        "not recovered: {pre:?} -> {post:?} ro={}",
                                        b.workspace.editor().read_only
                                    ));
                                }
                                if history && let Some(u) = &c.undo_to {
                                    let _ = cmd(&mut b, "undo", json!({}));
                                    let t = b.workspace.editor().text.to_string();
                                    if t != *u {
                                        p.push(format!(
                                            "UNDO lost after recovery: {t:?} expected {u:?}"
                                        ));
                                    }
                                }
                            }
                            rep.cell(&id, p);
                        }
                    }
                }
            }
        }
    }
}

/// Probe: after Keep Edits, undoing back to the old disk text reports a clean tab
/// whose text differs from disk; with the external identity acknowledged, a touch
/// never reconciles it.
#[test]
fn r20_matrix_probe_keep_then_undo_stale_clean() {
    let mut rep = Rep::new("probe_keep_undo");
    for st in [St::Auto, St::Chosen(SJIS), St::Main("utf8_dirty")] {
        for bg in [false, true] {
            let id = format!("{}|keep-undo|{}", st_name(st), if bg { "bg" } else { "fg" });
            let mut c = build(st, W1252, bg).unwrap();
            if !shown(&c.a).dirty {
                c.undo_to = Some(c.a.workspace.editor().text.to_string());
                edit(&mut c.a, "+k");
            }
            let codec = c.a.workspace.tabs[c.a.workspace.active]
                .saved_format
                .encoding
                .clone();
            let mut b = std::fs::read(&c.path).unwrap();
            b.extend(enc("external\n", &codec, false).unwrap());
            let mut o = Obs::new();
            let mut p = vec![];
            external(&mut c.a, &c.path, Some(&b), &mut o);
            let active = c.a.workspace.active;
            assert!(
                c.a.workspace.tabs[active].external.is_some(),
                "{id}: no conflict"
            );
            c.a.workspace.reload_external(active, false);
            let _ = cmd(&mut c.a, "undo", json!({}));
            let after_undo = shown(&c.a);
            let disk_text = strict(&codec, &std::fs::read(&c.path).unwrap()).unwrap();
            external(&mut c.a, &c.path, None, &mut o);
            let after_touch = shown(&c.a);
            if !after_touch.dirty && after_touch.text != disk_text {
                p.push(format!(
                    "STALE-CLEAN: tab clean, shows {:?}, disk has {:?} (after keep+undo, touch)",
                    after_touch.text, disk_text
                ));
            }
            rep.note(
                &id,
                format!(
                    "after undo dirty={} text={:?}",
                    after_undo.dirty, after_undo.text
                ),
            );
            // Every retained undo/redo point must remain dirty against the newly
            // acknowledged disk revision, not just the first state after Keep.
            for direction in ["undo", "redo"] {
                for _ in 0..8 {
                    let previous = shown(&c.a).text;
                    cmd(&mut c.a, direction, json!({})).unwrap();
                    let state = shown(&c.a);
                    if state.text != disk_text && !state.dirty {
                        p.push(format!("{direction} reached stale clean state {state:?}"));
                    }
                    if state.text == previous {
                        break;
                    }
                }
            }
            let retained = shown(&c.a).text;
            // Hot exit must retain the dirty buffer and its undo states too.
            match restart(&mut c.a, c.prof.path(), c.fallback, bg, true, || {}) {
                Ok((mut r, _)) => {
                    let restored = shown(&r);
                    if restored.text != retained || !restored.dirty {
                        p.push(format!("keep/undo restart lost edits: {restored:?}"));
                    }
                    cmd(&mut r, "save", json!({})).unwrap();
                    let saved = shown(&r);
                    if saved.dirty {
                        p.push("successful save still dirty".into());
                    }
                    external(&mut r, &c.path, None, &mut o);
                    let touched = shown(&r);
                    if touched.text != saved.text || touched.dirty || touched.codec != saved.codec {
                        p.push("touch after save changed state".into());
                    }
                }
                Err(e) => p.push(format!("restart {e}")),
            }
            rep.cell(&id, p);
        }
    }
}

/// Probe: main-format (legacy) revisions are proven by normalized text, so a
/// line-ending-only or BOM-only external change is treated as "unchanged".
#[test]
fn r20_matrix_probe_legacy_line_ending_and_bom_changes() {
    let mut rep = Rep::new("probe_legacy_format");
    let cases: &[(St, &str)] = &[
        (St::Auto, "crlf"),
        (St::Main("utf8_clean"), "crlf"),
        (St::Main("cp1252_clean"), "crlf"),
        (St::Main("sjis_clean"), "crlf"),
        (St::Main("utf8_dirty"), "crlf"),
        (St::Main("cp1252_dirty"), "crlf"),
        (St::Main("sjis_dirty"), "crlf"),
        (St::Auto, "add-bom"),
        (St::Main("utf8_clean"), "add-bom"),
        (St::Main("utf8_dirty"), "add-bom"),
        (St::Main("utf16le_bom_clean"), "drop-bom"),
    ];
    for &(st, change) in cases {
        for bg in [false, true] {
            let id = format!("{}|{change}|{}", st_name(st), if bg { "bg" } else { "fg" });
            let mut c = match build(st, W1252, bg) {
                Ok(c) => c,
                Err(e) => {
                    rep.cell(&id, vec![format!("SETUP {e}")]);
                    continue;
                }
            };
            let disk = std::fs::read(&c.path).unwrap();
            let bytes = match change {
                "crlf" => {
                    let mut b = Vec::new();
                    for &x in &disk {
                        if x == b'\n' {
                            b.push(b'\r');
                        }
                        b.push(x);
                    }
                    b
                }
                "add-bom" => [&[0xef, 0xbb, 0xbf][..], &disk].concat(),
                _ => disk[2..].to_vec(),
            };
            let before = shown(&c.a);
            let fmt_before = c.a.workspace.tabs[c.a.workspace.active].format.clone();
            let mut o = Obs::new();
            let mut p = vec![];
            external(&mut c.a, &c.path, Some(&bytes), &mut o);
            let active = c.a.workspace.active;
            let t = &c.a.workspace.tabs[active];
            let fmt = t.format.clone();
            let saved = t.saved_format.clone();
            if before.dirty {
                if t.external.is_none() {
                    p.push(format!(
                        "LEGACY dirty: no conflict for {change} change (bytes differ); saved_format now {:?}/{} bom={}",
                        saved.line_ending, saved.encoding, saved.bom
                    ));
                }
            } else {
                let want_crlf = change == "crlf";
                let ok = match change {
                    "crlf" => fmt.line_ending == vel_fileio::LineEnding::CrLf,
                    "add-bom" => fmt.bom,
                    _ => !fmt.bom,
                };
                if !ok {
                    p.push(format!(
                        "LEGACY clean: {change} change not reflected: format before {:?}/bom={} after {:?}/bom={} (crlf expected={want_crlf})",
                        fmt_before.line_ending, fmt_before.bom, fmt.line_ending, fmt.bom
                    ));
                }
            }
            // A subsequent edit + plain save: does it silently revert the external change?
            if c.a.workspace.tabs[active].external.is_none() {
                edit(&mut c.a, "+s");
                let _ = cmd(&mut c.a, "save", json!({}));
                let after = std::fs::read(&c.path).unwrap();
                let kept = match change {
                    "crlf" => after.windows(2).any(|w| w == b"\r\n"),
                    "add-bom" => after.starts_with(&[0xef, 0xbb, 0xbf]),
                    _ => !after.starts_with(&[0xff, 0xfe]),
                };
                if !kept {
                    p.push(format!(
                        "save after {change} change reverted it silently: {after:02x?}"
                    ));
                }
            }
            rep.cell(&id, p);
        }
    }
}

/// Probe: a document whose file became binary while the app was closed restores to the
/// streaming hex view (clean) or keeps its edits (dirty), non-modally, also for lazy tabs.
#[test]
fn r20_matrix_probe_binary_while_closed() {
    let mut rep = Rep::new("probe_binary_closed");
    let bins: [(&str, &[u8]); 2] = [
        ("nul_binary", b"abc\0\x01\x02def"),
        (
            "png",
            b"\x89PNG\r\n\x1a\n\0\0\0\rIHDR\0\0\0\x01\0\0\0\x01\x08\x02\0\0\0",
        ),
    ];
    for st in [
        St::Auto,
        St::Chosen(U16LE),
        St::Chosen(SJIS),
        St::SavedFallback(2),
        St::DirtyChosen,
        St::Main("utf16le_clean"),
        St::Main("utf8_dirty"),
    ] {
        for (bn, bytes) in bins {
            for bg in [false, true] {
                for lazy in [false, true] {
                    let id = format!(
                        "{}|{bn}-while-closed|lazy={lazy}|{}",
                        st_name(st),
                        if bg { "bg" } else { "fg" }
                    );
                    let mut c = match build(st, W1252, bg) {
                        Ok(c) => c,
                        Err(e) => {
                            rep.cell(&id, vec![format!("SETUP {e}")]);
                            continue;
                        }
                    };
                    let pre = shown(&c.a);
                    let path = c.path.clone();
                    if lazy {
                        let other = path.parent().unwrap().join("other.txt");
                        std::fs::write(&other, "other\n").unwrap();
                        let mut o = Obs::new();
                        open(&mut c.a, &other, &mut o).unwrap();
                    }
                    let mut p = vec![];
                    match restart(&mut c.a, c.prof.path(), c.fallback, bg, true, || {
                        let m = mtime(&path) + Duration::from_secs(2);
                        std::fs::write(&path, bytes).unwrap();
                        set_mtime(&path, m);
                    }) {
                        Err(e) => p.push(format!("restore error {e}")),
                        Ok((mut b, _prof)) => {
                            let index = b
                                .workspace
                                .tabs
                                .iter()
                                .position(|t| t.path.as_deref() == Some(path.as_path()))
                                .unwrap();
                            b.workspace.select(index);
                            let mut o = Obs::new();
                            pump(&mut b, &mut o, idle);
                            let post = shown(&b);
                            p.extend(modal(&b));
                            let msg = b.panels.message.clone();
                            if pre.dirty {
                                if post.text != pre.text || !post.dirty || post.binary {
                                    p.push(format!(
                                        "dirty doc after binary-while-closed: {pre:?} -> {post:?}"
                                    ));
                                }
                            } else if !post.binary {
                                p.push(format!(
                                    "binary file restored as text {:?} (notice {msg:?})",
                                    post.text
                                ));
                            }
                            if !(msg.contains("binary file") && msg.contains("doc.txt")) {
                                p.push(format!("binary notice missing {msg:?}"));
                            }
                            if post.chosen != pre.chosen {
                                p.push(format!("choice changed {pre:?} -> {post:?}"));
                            }
                        }
                    }
                    rep.cell(&id, p);
                }
            }
        }
    }
}

/// Probe: malformed bytes for the configured fallback on reload and restore paths:
/// replacement characters with a file-named, non-modal status notice.
#[test]
fn r20_matrix_probe_replacement_on_reload_and_restore() {
    let mut rep = Rep::new("probe_replacement");
    let bad: &[u8] = b"ok \x82\xff\x80 end\n";
    let exp = lossy(SJIS, bad);
    for bg in [false, true] {
        for path_kind in [
            "reload",
            "restore-changed-while-closed",
            "restore-unchanged",
        ] {
            let id = format!("replacement|{path_kind}|{}", if bg { "bg" } else { "fg" });
            let dir = tempfile::tempdir().unwrap();
            let path = std::fs::canonicalize(dir.path()).unwrap().join("doc.txt");
            std::fs::write(
                &path,
                if path_kind == "restore-unchanged" {
                    bad
                } else {
                    b"base\n" as &[u8]
                },
            )
            .unwrap();
            let (mut a, prof) = mk(SJIS, bg);
            let mut o = Obs::new();
            let mut p = vec![];
            a.panels.set_message(String::new());
            if let Err(e) = open(&mut a, &path, &mut o) {
                rep.cell(&id, vec![format!("open {e}")]);
                continue;
            }
            let target: App = match path_kind {
                "reload" => {
                    external(&mut a, &path, Some(bad), &mut o);
                    a
                }
                k => {
                    let changed = k == "restore-changed-while-closed";
                    match restart(&mut a, prof.path(), SJIS, bg, true, || {
                        if changed {
                            let m = mtime(&path) + Duration::from_secs(2);
                            std::fs::write(&path, bad).unwrap();
                            set_mtime(&path, m);
                        }
                    }) {
                        Ok((b, _)) => b,
                        Err(e) => {
                            rep.cell(&id, vec![format!("restart {e}")]);
                            continue;
                        }
                    }
                }
            };
            let sh = shown(&target);
            p.extend(modal(&target));
            let msg = target.panels.message.clone();
            if sh.text != exp || sh.codec != "Shift_JIS" || sh.binary {
                p.push(format!("expected {exp:?} Shift_JIS, got {sh:?}"));
            }
            if !(msg.contains("doc.txt") && msg.contains("replacement")) {
                p.push(format!("replacement notice missing {msg:?}"));
            }
            if sh.chosen {
                p.push("replacement fallback promoted to a choice".into());
            }
            rep.cell(&id, p);
        }
    }
}

/// Probe: a Reopen with Encoding that fails to read the file must not change the
/// persistent choice (or other tab state).
#[test]
fn r20_matrix_probe_failed_reopen_keeps_choice() {
    use std::os::unix::fs::PermissionsExt;
    let mut rep = Rep::new("probe_failed_reopen");
    for st in [St::Auto, St::Chosen(SJIS)] {
        let id = format!("{}|reopen-unreadable", st_name(st));
        let mut c = build(st, W1252, false).unwrap();
        edit(&mut c.a, "+pending");
        let mut obs = Obs::new();
        external(
            &mut c.a,
            &c.path,
            Some(b"external pending conflict\n"),
            &mut obs,
        );
        assert!(c.a.workspace.tabs[c.a.workspace.active].external.is_some());
        let pre = shown(&c.a);
        let before_id = c.a.workspace.tabs[c.a.workspace.active].disk_content;
        let _g = PermGuard(c.path.clone());
        std::fs::set_permissions(&c.path, std::fs::Permissions::from_mode(0o000)).unwrap();
        let r = cmd(&mut c.a, "reopen", json!({"encoding": GBK}));
        std::fs::set_permissions(&c.path, std::fs::Permissions::from_mode(0o644)).unwrap();
        let post = shown(&c.a);
        let mut p = vec![];
        if r.is_ok() {
            rep.note(&id, "reopen reported success".into());
        }
        if post.chosen != pre.chosen || post.preferred != pre.preferred {
            p.push(format!(
                "failed reopen changed choice: {:?}/{:?} -> {:?}/{:?} (err {r:?})",
                pre.chosen, pre.preferred, post.chosen, post.preferred
            ));
        }
        if post.text != pre.text {
            p.push(format!("failed reopen changed text {pre:?} -> {post:?}"));
        }
        let t = &c.a.workspace.tabs[c.a.workspace.active];
        if t.external.is_none() || t.disk_content != before_id || !post.dirty {
            p.push("failed Reopen changed pending conflict/revision/dirty state".into());
        }
        rep.cell(&id, p);
    }
}

/// Probe (timing): restore of an unchanged ~140 MB file, background, with history.
/// Reports time to first published prefix and to completion.
#[test]
#[ignore]
fn r20_matrix_probe_unchanged_large_restore_latency() {
    use std::io::Write;
    let mut rep = Rep::new("probe_large_restore");
    for codec in [U8, SJIS] {
        let dir = tempfile::tempdir().unwrap();
        let path = std::fs::canonicalize(dir.path()).unwrap().join("large.txt");
        let block = "日本語 hello!\n".repeat(65536);
        let bytes = enc(&block, codec, false).unwrap();
        {
            let mut f = std::fs::File::create(&path).unwrap();
            for _ in 0..128 {
                f.write_all(&bytes).unwrap();
            }
        }
        let (mut a, prof) = mk(W1252, true);
        let mut o = Obs::new();
        open(&mut a, &path, &mut o).unwrap();
        if codec != U8 {
            cmd(&mut a, "reopen", json!({"encoding": codec})).unwrap();
        }
        assert!(std::fs::metadata(&path).unwrap().len() >= 100 * 1024 * 1024);
        for history in [true, false] {
            let mut first_ms = Vec::new();
            for run in 0..3 {
                if !history {
                    a.workspace
                        .settings
                        .set(Layer::User, "hot_exit", json!("disabled"));
                }
                a.save_workspace_checkpoint().unwrap();
                a.workspace
                    .settings
                    .set(Layer::User, "hot_exit", json!("always"));
                let rec = vel_session::load(&session_file(prof.path()));
                let (mut b, _p) = mk(W1252, true);
                let start = Instant::now();
                b.workspace
                    .restore_window(&rec.session.windows[0], &rec.session.documents)
                    .unwrap();
                let mut first = None;
                let deadline = Instant::now() + Duration::from_secs(120);
                loop {
                    frame(&mut b);
                    if first.is_none() && !b.workspace.editor().text.is_empty() {
                        first = Some(start.elapsed());
                    }
                    if idle(&b) && first.is_some() {
                        break;
                    }
                    if Instant::now() > deadline {
                        break;
                    }
                    std::thread::park_timeout(Duration::from_millis(1));
                }
                let done = start.elapsed();
                let id = format!("large-restore|{}|hist={history}|run={run}", canon(codec));
                rep.note(
                    &id,
                    format!(
                        "first_prefix_ms {:.1} complete_ms {:.1} len {}",
                        first.map_or(-1.0, |d| d.as_secs_f64() * 1000.),
                        done.as_secs_f64() * 1000.,
                        b.workspace.editor().text.len_bytes()
                    ),
                );
                assert!(idle(&b), "restore did not complete");
                let first = first.expect("restore did not publish content");
                assert!(first < done, "no progressive snapshot before completion");
                assert_eq!(b.workspace.editor().text.len_bytes(), block.len() * 128);
                assert_eq!(
                    b.workspace.tabs[b.workspace.active].format.encoding,
                    canon(codec)
                );
                assert!(modal(&b).is_empty());
                first_ms.push(first.as_secs_f64() * 1000.);
                rep.cell(&id, vec![]);
            }
            // A hardware-independent timing gate: use the same probe from an
            // archived parent build. The full ignored matrix is also runnable
            // without a baseline and still checks progressive/correct completion.
            if let Some(parent) = std::env::var_os("R20_RESTORE_PARENT_REPORT") {
                let parent = std::fs::read_to_string(parent).unwrap();
                let prefix = format!("NOTE\tlarge-restore|{}|hist={history}|", canon(codec));
                let mut baseline: Vec<f64> = parent
                    .lines()
                    .filter(|line| line.starts_with(&prefix))
                    .map(|line| {
                        line.split("first_prefix_ms ")
                            .nth(1)
                            .unwrap()
                            .split_whitespace()
                            .next()
                            .unwrap()
                            .parse()
                            .unwrap()
                    })
                    .collect();
                assert_eq!(
                    baseline.len(),
                    3,
                    "parent probe must supply three samples per case"
                );
                baseline.sort_by(f64::total_cmp);
                first_ms.sort_by(f64::total_cmp);
                assert!(
                    first_ms[1] <= baseline[1] * 1.5,
                    "{codec}, history={history}: first snapshot {} ms > parent {} ms * 1.5",
                    first_ms[1],
                    baseline[1]
                );
            }
        }
    }
}

#[test]
fn r20_matrix_same_stamp_different_bytes_finishes_with_policy_text() {
    for bg in [false, true] {
        for history in [false, true] {
            let dir = tempfile::tempdir().unwrap();
            let path = dir.path().join("same-stamp.txt");
            let original = b"caf\xe9 old\n".repeat(300_000);
            let changed = "café ok\n".repeat(300_000);
            assert_eq!(original.len(), changed.len());
            std::fs::write(&path, &original).unwrap();
            let (mut a, prof) = mk(W1252, bg);
            open(&mut a, &path, &mut Obs::new()).unwrap();
            cmd(&mut a, "reopen", json!({"encoding":U8})).unwrap();
            assert_eq!(shown(&a).codec, "windows-1252");
            let stamp = mtime(&path);
            let (mut b, _profile) = restart(&mut a, prof.path(), W1252, bg, history, || {
                std::fs::write(&path, changed.as_bytes()).unwrap();
                set_mtime(&path, stamp);
            })
            .unwrap();
            frame(&mut b);
            let result = shown(&b);
            assert_eq!(result.text, changed);
            assert_eq!(result.codec, U8);
            assert!(!result.dirty);
            assert!(modal(&b).is_empty());
        }
    }
}

#[test]
fn r20_matrix_legacy_dirty_closed_format_change_conflicts() {
    for case in [
        "utf8_dirty",
        "cp1252_dirty",
        "sjis_dirty",
        "utf8_bom_dirty",
        "utf16le_bom_dirty",
    ] {
        for bg in [false, true] {
            for operation in ["line_endings", "bom"] {
                let src = main_fixtures().join(case);
                let dir = tempfile::tempdir().unwrap();
                let path = dir.path().join("doc.txt");
                let mut json: Value =
                    serde_json::from_slice(&std::fs::read(src.join("session.json")).unwrap())
                        .unwrap();
                let codec = std::fs::read_to_string(src.join("encoding.txt")).unwrap();
                let expected = std::fs::read_to_string(src.join("expected.txt")).unwrap();
                json["documents"][0]["path"] = json!(path);
                let original = std::fs::read(src.join("doc.txt")).unwrap();
                let original_bom = bom_of(&original);
                let text = strict(&codec, &original[original_bom.map_or(0, |(_, n)| n)..]).unwrap();
                let bytes = if operation == "line_endings" {
                    enc(&text.replace('\n', "\r\n"), &codec, original_bom.is_some()).unwrap()
                } else {
                    let unicode = if codec.starts_with("UTF-") {
                        codec.as_str()
                    } else {
                        U8
                    };
                    enc(&text, unicode, original_bom.is_none()).unwrap()
                };
                std::fs::write(&path, bytes).unwrap();
                let ns = json["documents"][0]["disk"]["modified_ns"]
                    .as_u64()
                    .unwrap();
                set_mtime(
                    &path,
                    SystemTime::UNIX_EPOCH + Duration::from_nanos(ns) + Duration::from_secs(2),
                );
                let session = dir.path().join("legacy.sublime-session");
                std::fs::write(&session, serde_json::to_vec(&json).unwrap()).unwrap();
                let (a, _prof) = restore_from(&session, W1252, bg).unwrap();
                let t = &a.workspace.tabs[a.workspace.active];
                assert_eq!(t.editor.text, expected.as_str(), "{case}/{bg}/{operation}");
                assert!(t.dirty());
                assert!(
                    t.external.is_some(),
                    "{case}/{bg}/{operation}: format-only rewrite lost"
                );
                assert!(modal(&a).is_empty());
            }
        }
    }
}

// Preserve the focused regressions from the previous matrix adaptation.
#[test]
fn r20_explicit_choice_and_revision_encoding_are_independent() {
    for bg in [false, true] {
        for (k, next, codec) in [
            (0, "日本語かな next\n", SJIS),
            (1, "naïve café next\n", U8),
            (2, "new UTF-16 text\n", U16LE),
        ] {
            let mut c = build(St::SavedFallback(k), W1252, bg).unwrap();
            let choice = c.choice.unwrap();
            let before = shown(&c.a);
            assert!(before.chosen);
            assert_eq!(before.preferred.as_deref(), Some(choice));
            let mut o = Obs::new();
            assert!(external(&mut c.a, &c.path, None, &mut o));
            assert_eq!(shown(&c.a), before);
            let (mut a, prof) = restart(&mut c.a, c.prof.path(), W1252, bg, true, || {}).unwrap();
            assert_eq!(shown(&a), before);
            let bytes = enc(next, codec, false).unwrap();
            assert!(external(&mut a, &c.path, Some(&bytes), &mut o));
            assert_eq!(a.workspace.editor().text, next);
            let tab = &a.workspace.tabs[a.workspace.active];
            assert!(tab.encoding_chosen);
            assert_eq!(tab.preferred_encoding.as_deref(), Some(choice));
            assert_eq!(tab.format.encoding, canon(codec));
            assert!(a.workspace.messages.is_empty());
            drop(prof);
        }
    }
}

#[test]
fn r20_malformed_fallback_revision_survives_touch_and_restart() {
    for bg in [false, true] {
        for bytes in [b"\xef\xbb\xbf\x80".as_slice(), b"\xff\xfea", b"caf\xe9 ok"] {
            for fallback in [W1252, SJIS, U8] {
                let dir = tempfile::tempdir().unwrap();
                let path = std::fs::canonicalize(dir.path())
                    .unwrap()
                    .join("malformed.txt");
                std::fs::write(&path, bytes).unwrap();
                let (mut a, prof) = mk(fallback, bg);
                let mut o = Obs::new();
                open(&mut a, &path, &mut o).unwrap();
                let before = shown(&a);
                assert!(!before.binary);
                assert!(!before.chosen);
                assert!(external(&mut a, &path, None, &mut o));
                assert_eq!(shown(&a), before);
                let (b, _prof) = restart(&mut a, prof.path(), fallback, bg, true, || {}).unwrap();
                assert_eq!(shown(&b), before, "bytes={bytes:?} fallback={fallback}");
                assert!(b.workspace.messages.is_empty());
            }
        }
    }
}

