#[test]
fn r20_main_error_placeholder_keeps_revision_proof_on_restart() {
    use std::os::unix::fs::PermissionsExt;
    let fixture = main_fixtures().join("sjis_clean");
    for bg in [false, true] {
        let dir = tempfile::tempdir().unwrap();
        let path = std::fs::canonicalize(dir.path()).unwrap().join("doc.txt");
        let json = std::fs::read_to_string(fixture.join("session.json")).unwrap();
        let wire: Value = serde_json::from_str(&json).unwrap();
        let old = wire["documents"][0]["path"].as_str().unwrap();
        let json = json.replace(old, path.to_str().unwrap());
        std::fs::copy(fixture.join("doc.txt"), &path).unwrap();
        set_mtime(
            &path,
            SystemTime::UNIX_EPOCH
                + Duration::from_nanos(
                    wire["documents"][0]["disk"]["modified_ns"]
                        .as_u64()
                        .unwrap(),
                ),
        );
        let session = dir.path().join("legacy-session.json");
        std::fs::write(&session, json).unwrap();
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o000)).unwrap();
        let (mut a, prof) = restore_from(&session, W1252, bg).unwrap();
        assert!(a.workspace.editor().read_only);
        let (mut a, _prof) = restart(&mut a, prof.path(), W1252, bg, true, || {}).unwrap();
        assert!(a.workspace.editor().read_only);
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o644)).unwrap();
        assert!(external(&mut a, &path, None, &mut Obs::new()));
        assert_eq!(
            a.workspace.editor().text,
            std::fs::read_to_string(fixture.join("expected.txt"))
                .unwrap()
                .as_str()
        );
        assert_eq!(shown(&a).codec, "Shift_JIS");
        assert!(!shown(&a).chosen);
        assert!(a.workspace.messages.is_empty());
        assert!(!a.workspace.editor().read_only);
    }
}
